/* Kelas IX — Semester 1 — Akhlak Terpuji: Sabar, Syukur, Istiqamah & Husnuzan — 50 soal */
window.BSRegister({
'id':'k9-akhlak-terpuji-9','grade':9,'semester':1,'order':16,
'title':'Akhlak Terpuji: Sabar, Syukur, Istiqamah & Husnuzan',
'desc':'Pengertian sabar, syukur, istiqamah, dan husnuzan beserta dalilnya, macam-macam sabar, wujud syukur, cara menjaga istiqamah, perbedaan husnuzan dengan sikap mudah percaya, serta penerapannya dalam kehidupan sehari-hari.',
'kd':'Menganalisis pengertian sabar, syukur, istiqamah, dan husnuzan beserta dalilnya, serta menampilkan perilaku sabar, syukur, istiqamah, dan husnuzan dalam kehidupan sehari-hari.',
'questions':[{level:'HOTS',indicator:'Menentukan pengertian sabar yang benar',text:'Pengertian sabar yang paling tepat adalah ...',options:['menahan diri dari seluruh perasaan sedih agar hati tetap tenang dalam setiap keadaan','menunda keinginan dalam waktu yang lama agar keinginan itu hilang dengan sendirinya','menahan diri dari keluhan ketika menghadapi keadaan yang tidak menyenangkan','menahan diri dalam tiga keadaan yaitu menahan diri untuk tetap taat kepada Allah walaupun terasa berat, menahan diri dari perbuatan maksiat walaupun godaannya kuat, dan menahan diri dari keluhan serta keputusasaan ketika tertimpa musibah, sehingga sabar bukan sekadar diam melainkan kesanggupan menjaga arah perilaku dan ucapan agar tetap sesuai dengan ketentuan agama dalam keadaan yang paling menekan, dan sabar disertai usaha mengubah keadaan yang dapat diubah karena sabar bukan bentuk menyerah pada keadaan'],answer:3,explanation:'Q.S. al-Baqarah [2]: 153 berbunyi mohonlah pertolongan dengan sabar dan salat, sesungguhnya Allah bersama orang-orang yang sabar. Q.S. Ali Imran [3]: 200 berbunyi wahai orang-orang yang beriman bersabarlah kalian dan kuatkanlah kesabaran kalian serta bersiap siagalah dan bertakwalah kepada Allah agar kalian beruntung. Hadis juga membagi sabar menjadi tiga yaitu sabar dalam ketaatan, sabar dari maksiat, dan sabar atas musibah. Q.S. al-Baqarah [2]: 155-156 menyebut orang yang sabar sebagai orang yang mengucapkan kalimat istirja ketika tertimpa musibah. Hadis juga menyebut bahwa kesabaran itu pada hentakan pertama. Adapun menahan diri dari seluruh perasaan sedih bukan syarat sabar karena kesedihan merupakan perasaan manusiawi yang dialami juga oleh para nabi selama tidak disertai ucapan atau perbuatan yang menunjukkan ketidakrelaan terhadap ketentuan Allah, dan menunda keinginan hingga hilang bukan pengertian sabar karena sabar berkaitan dengan menjaga ketaatan dan menjauhi maksiat.'},
{level:'HOTS',indicator:'Menganalisis macam-macam sabar',text:'Sabar terbagi menjadi sabar dalam ketaatan, sabar dari maksiat, dan sabar atas musibah. Analisis yang paling tepat terhadap ketiga macam sabar tersebut adalah ...',options:['sabar dari maksiat merupakan yang paling berat karena godaan maksiat selalu lebih kuat daripada dorongan ketaatan','sabar atas musibah tidak termasuk sabar yang sesungguhnya karena musibah tidak dapat diubah sehingga menerimanya bukan kesabaran melainkan ketidakberdayaan','sabar dalam ketaatan merupakan yang paling utama karena ketaatan merupakan tujuan hidup','ketiga macam sabar mencakup seluruh keadaan manusia karena setiap waktu manusia berada dalam salah satu dari tiga keadaan yaitu sedang melaksanakan ketaatan sehingga memerlukan kesabaran untuk menyempurnakannya dan melanjutkannya, sedang menghadapi godaan maksiat sehingga memerlukan kesabaran untuk menolaknya, atau sedang tertimpa musibah sehingga memerlukan kesabaran untuk menerimanya tanpa kehilangan pahala, dan pembagian itu menunjukkan bahwa sabar merupakan sikap yang diperlukan secara berkelanjutan bukan hanya ketika menghadapi keadaan yang berat saja, serta menunjukkan bahwa sabar dalam ketaatan dan sabar dari maksiat merupakan sabar yang berkaitan dengan pilihan manusia sedangkan sabar atas musibah berkaitan dengan ketentuan yang tidak dipilihnya'],answer:3,explanation:'Hadis juga membagi sabar menjadi tiga yaitu sabar dalam ketaatan kepada Allah, sabar dari maksiat kepada Allah, dan sabar atas musibah dari Allah. Q.S. Maryam [19]: 65 berbunyi Tuhan langit dan bumi serta apa yang ada di antara keduanya maka sembahlah Dia dan bersabarlah dalam beribadah kepada-Nya. Q.S. Yusuf [12]: 90 menggambarkan ucapan bahwa barangsiapa bertakwa dan bersabar maka sesungguhnya Allah tidak menyia-nyiakan pahala orang yang berbuat kebaikan. Q.S. al-Baqarah [2]: 155-156 menyebut orang yang sabar ketika tertimpa musibah. Hadis juga menyebut bahwa kesabaran itu pada hentakan pertama. Q.S. Ali Imran [3]: 200 memerintahkan bersabar dan menguatkan kesabaran. Adapun tidak dinyatakan bahwa salah satu macam sabar lebih utama secara mutlak karena ketiganya diperlukan dalam keadaan yang berbeda, dan sabar atas musibah merupakan sabar yang sesungguhnya karena yang dinilai adalah sikap hati dan ucapan bukan kemampuan mengubah keadaan.'},
{level:'HOTS',indicator:'Menentukan pengertian syukur',text:'Pengertian syukur yang paling tepat adalah ...',options:['mengakui bahwa nikmat berasal dari Allah lalu memuji-Nya dengan lisan dan menggunakan nikmat itu sesuai dengan tujuan pemberiannya sehingga tidak digunakan untuk bermaksiat, dan syukur mencakup tiga unsur yaitu mengakui dalam hati bahwa seluruh nikmat berasal dari Allah bukan semata hasil kemampuan diri, memuji Allah dengan lisan melalui ucapan tahmid dan menyebut nikmat itu sebagai karunia-Nya, serta menggunakan nikmat dalam ketaatan sehingga mata digunakan untuk melihat yang dibolehkan, harta digunakan untuk menunaikan haknya, dan ilmu digunakan untuk memberi manfaat, dan syukur yang demikian menghasilkan tambahan nikmat karena Allah menjanjikan tambahan bagi orang yang bersyukur','mengucapkan kalimat tahmid ketika memperoleh nikmat','menunjukkan rasa senang yang berlebihan ketika memperoleh nikmat agar diketahui bahwa nikmat itu besar','memberi sebagian dari nikmat yang diperoleh kepada orang lain sebagai bentuk terima kasih kepada pihak yang telah membantu'],answer:0,explanation:'Q.S. Ibrahim [14]: 7 berbunyi dan ingatlah ketika Tuhanmu memaklumkan jika kalian bersyukur maka Aku menambah nikmat kepada kalian dan jika kalian kufur maka sesungguhnya azab-Ku sangat pedih. Q.S. ad-Duha [93]: 11 berbunyi dan terhadap nikmat Tuhanmu hendaklah engkau menyebut-nyebutnya, dalam pengertian mengakui dan mensyukuri bukan membanggakan. Q.S. Saba [34]: 13 berbunyi bekerjalah wahai keluarga Daud untuk bersyukur, dan sedikit sekali dari hamba-hamba-Ku yang bersyukur, yang menunjukkan bahwa syukur diwujudkan melalui amal. Hadis juga menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah. Hadis juga menyebut bahwa Allah ridha kepada hamba yang memakan makanan lalu memuji Allah atasnya dan meminum minuman lalu memuji Allah atasnya. Q.S. al-Baqarah [2]: 152 memerintahkan mengingat Allah dan bersyukur serta tidak kufur. Adapun menunjukkan rasa senang yang berlebihan bukan syukur karena dapat mengarah kepada kesombongan, dan memberi kepada orang lain merupakan bagian dari menggunakan nikmat untuk ketaatan tetapi bukan seluruh makna syukur.'},
{level:'HOTS',indicator:'Menganalisis pengertian istiqamah',text:'Pengertian istiqamah yang paling tepat adalah ...',options:['tidak berubah pendirian dalam seluruh persoalan walaupun terdapat dalil yang menunjukkan bahwa pendiriannya keliru','melaksanakan ibadah yang wajib saja secara teratur agar tidak terbebani oleh ibadah yang sunah','tetap berada di jalan yang benar secara berkelanjutan walaupun terdapat godaan untuk menyimpang atau berhenti, sehingga istiqamah mencakup keteguhan dalam akidah tanpa terpengaruh oleh keyakinan yang menyimpang, keteraturan dalam melaksanakan ibadah walaupun sedikit kadarnya karena amal yang berkelanjutan lebih dicintai Allah daripada amal yang banyak tetapi terhenti, kesungguhan dalam berakhlak baik walaupun keadaan tidak mendukung, dan kesabaran dalam menghadapi akibat dari keteguhan itu karena memilih jalan yang benar sering menghasilkan ujian, dan istiqamah tidak menuntut kesempurnaan mutlak melainkan menuntut kesungguhan untuk kembali kepada jalan yang benar apabila terjadi kekeliruan','melaksanakan seluruh perintah agama dengan sempurna tanpa kekurangan sedikit pun'],answer:2,explanation:'Q.S. Fussilat [41]: 30-31 berbunyi sesungguhnya orang-orang yang berkata Tuhan kami adalah Allah kemudian mereka beristiqamah maka malaikat turun kepada mereka dengan mengatakan janganlah kalian takut dan janganlah bersedih serta bergembiralah dengan surga yang dijanjikan kepada kalian. Q.S. Hud [11]: 112 berbunyi maka beristiqamahlah sebagaimana diperintahkan kepadamu dan kepada orang yang bertobat bersamamu serta janganlah melampaui batas. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa orang yang paling dicintai Allah adalah yang paling bermanfaat bagi manusia. Q.S. al-Fatihah [1]: 6 menyebut doa memohon petunjuk ke jalan yang lurus. Hadis juga menganjurkan istighfar dan tobat sehingga kekeliruan tidak menghentikan istiqamah melainkan diperbaiki melalui tobat. Adapun tidak berubah pendirian walaupun terdapat dalil yang menunjukkan kekeliruan bukan istiqamah melainkan keras kepala karena istiqamah berada di atas kebenaran bukan di atas pendapat pribadi.'},
{level:'HOTS',indicator:'Menentukan pengertian husnuzan',text:'Pengertian husnuzan yang paling tepat adalah ...',options:['berbaik sangka kepada orang yang telah dikenal baik dan berburuk sangka kepada orang yang belum dikenal','berbaik sangka kepada seluruh orang tanpa kecuali sehingga tidak pernah mencurigai siapa pun','berbaik sangka dengan tidak melakukan verifikasi atas informasi karena verifikasi menunjukkan adanya kecurigaan','berbaik sangka kepada Allah terhadap seluruh ketentuan-Nya dan berbaik sangka kepada sesama manusia dengan tidak menilai buruk perbuatan atau keadaan mereka tanpa bukti yang jelas, sehingga husnuzan merupakan sikap menahan diri dari menilai buruk sebelum terdapat petunjuk yang cukup dan mencari kemungkinan penjelasan yang baik atas perbuatan yang tampak meragukan, dan husnuzan tidak berarti menghilangkan kewaspadaan yang diperlukan karena kewaspadaan berbeda dari berburuk sangka sebab kewaspadaan merupakan langkah pencegahan tanpa menilai buruk sedangkan berburuk sangka merupakan penilaian terhadap keadaan batin orang lain tanpa dasar, serta husnuzan yang paling utama adalah berbaik sangka kepada Allah karena buruk sangka kepada Allah merupakan sifat yang dicela dalam Al-Quran'],answer:3,explanation:'Q.S. al-Hujurat [49]: 12 berbunyi wahai orang-orang yang beriman jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa. Hadis qudsi juga menyebut bahwa Aku sesuai dengan persangkaan hamba-Ku terhadap-Ku. Q.S. al-Fath [48]: 6 mengecam orang yang berburuk sangka kepada Allah. Q.S. an-Nur [24]: 12 menegur orang beriman yang tidak berbaik sangka ketika mendengar berita bohong dan menyebut mengapa mereka tidak berkata ini adalah kebohongan yang nyata. Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Q.S. al-Hujurat [49]: 6 memerintahkan meneliti kebenaran berita dari orang fasik, yang menunjukkan bahwa verifikasi bukan bentuk buruk sangka melainkan kehati-hatian yang diperintahkan. Adapun berbaik sangka kepada seluruh orang tanpa kewaspadaan dapat menghasilkan kerugian karena agama tetap memerintahkan menjaga diri dari pihak yang menunjukkan tanda bahaya, dan berburuk sangka kepada orang yang belum dikenal bukan sikap yang diajarkan karena penilaian buruk memerlukan dasar.'},
{level:'HOTS',indicator:'Menganalisis dalil tentang keutamaan sabar',text:'Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar akan disempurnakan pahalanya tanpa perhitungan. Analisis yang paling tepat terhadap keutamaan tersebut adalah ...',options:['keutamaan itu menunjukkan bahwa pahala kesabaran tidak dibatasi oleh hitungan tertentu sebagaimana pahala amal yang lain','keutamaan itu menunjukkan bahwa pahala tanpa perhitungan hanya diberikan kepada para nabi sehingga orang biasa tidak memperolehnya','keutamaan itu menunjukkan bahwa pahala kesabaran tidak dibatasi oleh hitungan tertentu karena Allah menyempurnakannya tanpa perhitungan, sedangkan pahala amal kebaikan yang lain disebutkan kelipatannya seperti sepuluh hingga tujuh ratus kali lipat, dan keutamaan itu juga menunjukkan bahwa sabar merupakan amal yang nilainya paling luas karena sabar menyertai seluruh amal sehingga salat memerlukan sabar untuk melaksanakannya, zakat memerlukan sabar untuk mengeluarkan harta, dan puasa merupakan bentuk sabar yang paling nyata, serta menunjukkan bahwa Allah bersama orang yang sabar sehingga kebersamaan itu merupakan dukungan yang tidak diperoleh oleh orang yang tidak sabar','keutamaan itu berarti sabar lebih utama daripada seluruh amal sehingga tidak perlu melaksanakan amal yang lain'],answer:2,explanation:'Q.S. az-Zumar [39]: 10 berbunyi katakanlah wahai hamba-hamba-Ku yang beriman bertakwalah kepada Tuhan kalian, bagi orang-orang yang berbuat kebaikan di dunia ini memperoleh kebaikan, dan bumi Allah itu luas, sesungguhnya hanya orang-orang yang bersabarlah yang disempurnakan pahalanya tanpa perhitungan. Q.S. al-Baqarah [2]: 153 berbunyi sesungguhnya Allah bersama orang-orang yang sabar. Hadis juga menyebut bahwa puasa merupakan separuh kesabaran. Q.S. al-Baqarah [2]: 261 memberi perumpamaan satu biji yang menumbuhkan tujuh tangkai dan pada setiap tangkai terdapat seratus biji sebagai perbandingan pahala amal yang lain. Q.S. Ali Imran [3]: 200 memerintahkan bersabar dan menguatkan kesabaran. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga sabar menyertai keberlanjutan amal. Adapun sabar bukan pengganti amal yang lain melainkan sikap yang menyertai amal, dan pahala tanpa perhitungan diberikan kepada orang yang bersabar dari kalangan orang beriman bukan hanya kepada para nabi.'},
{level:'HOTS',indicator:'Menentukan wujud syukur dengan hati, lisan, dan perbuatan',text:'Wujud syukur dengan hati, lisan, dan perbuatan yang paling tepat adalah ...',options:['mengakui dalam hati bahwa nikmat berasal dari Allah, memuji Allah dengan lisan, dan menggunakan nikmat dalam ketaatan','mengakui dalam hati bahwa nikmat berasal dari Allah dan tidak perlu memuji dengan lisan karena pujian dalam hati telah cukup','mengakui dalam hati bahwa seluruh nikmat berasal dari Allah sehingga tidak merasa berhak memperolehnya karena kemampuannya sendiri, memuji Allah dengan lisan melalui ucapan tahmid dan menyebut nikmat itu sebagai karunia-Nya tanpa maksud membanggakan diri di hadapan manusia, menggunakan nikmat dalam ketaatan sehingga kesehatan digunakan untuk beribadah dan bekerja yang halal, harta digunakan untuk menunaikan zakat dan membantu pihak yang memerlukan, ilmu digunakan untuk memberi manfaat, dan waktu digunakan untuk amal yang berkelanjutan, serta tidak menggunakan nikmat untuk bermaksiat karena menggunakan nikmat untuk bermaksiat merupakan bentuk kufur nikmat yang paling nyata','memuji Allah dengan lisan secara berulang walaupun nikmat itu tidak digunakan untuk ketaatan karena pujian merupakan wujud syukur yang paling utama'],answer:2,explanation:'Q.S. Saba [34]: 13 berbunyi bekerjalah wahai keluarga Daud untuk bersyukur, dan sedikit sekali dari hamba-hamba-Ku yang bersyukur, yang menunjukkan bahwa syukur diwujudkan melalui amal. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Q.S. ad-Duha [93]: 11 berbunyi dan terhadap nikmat Tuhanmu hendaklah engkau menyebut-nyebutnya. Hadis juga menyebut bahwa Allah ridha kepada hamba yang memakan makanan lalu memuji Allah atasnya dan meminum minuman lalu memuji Allah atasnya. Q.S. an-Nahl [16]: 18 berbunyi dan jika kalian menghitung nikmat Allah niscaya kalian tidak dapat menghitungnya. Hadis juga menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah. Adapun mengakui dalam hati tanpa memuji dengan lisan dan tanpa menggunakan nikmat dalam ketaatan bukan syukur yang sempurna karena syukur mencakup tiga unsur yang tidak dapat dipisahkan, dan memuji dengan lisan tanpa menggunakan nikmat dalam ketaatan merupakan syukur yang tidak lengkap karena menggunakan nikmat untuk bermaksiat merupakan bentuk kufur nikmat.'},
{level:'HOTS',indicator:'Menganalisis cara menjaga istiqamah dalam beribadah',text:'Cara menjaga istiqamah dalam beribadah yang paling tepat adalah ...',options:['memulai dengan kadar yang ringan dan dapat dipertahankan secara berkelanjutan lalu menambah secara bertahap','menetapkan jadwal ibadah yang padat agar seluruh waktu terisi sehingga tidak ada kesempatan untuk malas','memulai dengan kadar yang berat agar terbiasa sehingga kadar yang ringan terasa mudah dilaksanakan','memulai dengan kadar yang ringan dan dapat dipertahankan secara berkelanjutan karena amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga memulai dengan kadar yang berat berisiko berhenti ketika keadaan tidak mendukung, menambah secara bertahap ketika kadar yang ringan telah menjadi kebiasaan karena penambahan yang bertahap lebih kokoh daripada penambahan yang mendadak, mengikat ibadah dengan waktu atau keadaan tertentu sehingga lebih mudah diingat seperti membaca Al-Quran setelah salat Subuh atau berzikir sebelum tidur, mengganti ibadah yang terlewat pada waktu yang memungkinkan karena mengganti merupakan bentuk kesungguhan menjaga keberlanjutan, meminta pertolongan kepada Allah melalui doa memohon keteguhan hati karena hati manusia berubah-ubah, serta tidak merasa gagal ketika terlewat sekali atau dua kali karena perasaan gagal yang berlebihan dapat menghasilkan berhenti sepenuhnya'],answer:3,explanation:'Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa beramallah sesuai kemampuan kalian karena Allah tidak jenuh hingga kalian jenuh. Hadis juga menganjurkan doa memohon keteguhan hati dan menyebut bahwa hati manusia berada di antara dua jari dari jari-jari ar-Rahman yang Dia bolak-balikkan sesuai kehendak-Nya. Q.S. Hud [11]: 112 memerintahkan beristiqamah dan melarang melampaui batas, yang menunjukkan bahwa berlebihan dalam beragama bukan bagian dari istiqamah. Hadis juga melarang membebani diri dan menyebut bahwa agama ini mudah sehingga tidak ada orang yang mempersulit diri dalam agama melainkan agama itu mengalahkannya. Hadis juga menyebut bahwa amal yang terlewat karena uzur tetap dicatat pahalanya bagi orang yang biasa mengerjakannya, sehingga mengganti dan tidak merasa gagal merupakan sikap yang benar.'},
{level:'HOTS',indicator:'Menentukan perbedaan husnuzan dengan sikap mudah percaya',text:'Perbedaan antara husnuzan dan sikap mudah percaya yang paling tepat adalah ...',options:['husnuzan merupakan sikap hati yang tidak menilai buruk tanpa dasar sedangkan mudah percaya merupakan kelalaian dalam menilai informasi','husnuzan berarti tidak memverifikasi informasi karena verifikasi menunjukkan buruk sangka kepada pihak yang menyampaikan','mudah percaya merupakan bentuk husnuzan yang berlebihan sehingga keduanya merupakan satu sikap yang sama','husnuzan merupakan sikap hati yang menahan diri dari menilai buruk perbuatan atau keadaan orang lain tanpa dasar yang cukup dan mencari kemungkinan penjelasan yang baik, sedangkan mudah percaya merupakan kelalaian dalam menilai informasi sehingga menerima seluruh yang disampaikan tanpa verifikasi, dan keduanya berada dalam bidang yang berbeda karena husnuzan berkaitan dengan penilaian terhadap keadaan batin orang lain sedangkan verifikasi berkaitan dengan kebenaran informasi yang disampaikan, sehingga seorang muslim dapat berhusnuzan kepada orang yang menyampaikan informasi sekaligus memverifikasi informasi itu karena perintah meneliti berita tidak berarti menilai buruk orang yang menyampaikannya'],answer:3,explanation:'Q.S. al-Hujurat [49]: 12 berbunyi jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa. Q.S. al-Hujurat [49]: 6 berbunyi wahai orang-orang yang beriman jika datang kepada kalian orang fasik membawa suatu berita maka telitilah kebenarannya agar kalian tidak mencelakakan suatu kaum karena kebodohan yang kemudian kalian menyesali perbuatan itu, yang menunjukkan bahwa meneliti berita merupakan perintah dan bukan bentuk buruk sangka. Hadis juga menyebut bahwa cukuplah seseorang dikatakan berdusta apabila ia menceritakan segala yang didengarnya, sehingga menyampaikan tanpa verifikasi merupakan kelalaian. Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Q.S. an-Nur [24]: 12 menegur orang beriman yang tidak berbaik sangka ketika mendengar berita bohong, yang menunjukkan bahwa husnuzan berkaitan dengan sikap hati terhadap pihak yang diberitakan. Adapun husnuzan tidak berarti meninggalkan verifikasi karena keduanya berada dalam bidang yang berbeda.'},
{level:'HOTS',indicator:'Menganalisis hikmah diperintahkannya bersyukur',text:'Bersyukur diperintahkan dan Allah menjanjikan tambahan nikmat bagi orang yang bersyukur. Analisis yang paling tepat terhadap hikmah perintah tersebut adalah ...',options:['hikmahnya karena bersyukur merupakan ibadah yang paling mudah sehingga tidak memerlukan kesungguhan dalam melaksanakannya','hikmahnya agar manusia menyadari bahwa seluruh nikmat berasal dari Allah sehingga menggunakan nikmat itu sesuai dengan tujuan pemberiannya','hikmahnya agar nikmat manusia bertambah banyak sehingga kehidupan dunia menjadi lebih nyaman','hikmahnya agar manusia menyadari bahwa seluruh nikmat berasal dari Allah sehingga tidak sombong atas apa yang diperolehnya dan tidak merasa berhak memperolehnya karena kemampuannya sendiri, dan kesadaran itu menghasilkan penggunaan nikmat sesuai dengan tujuan pemberiannya karena orang yang menyadari sumber nikmat akan berhati-hati dalam menggunakannya, serta hikmah itu juga menghasilkan ketenangan karena orang yang bersyukur tidak disibukkan oleh keinginan yang tidak terpenuhi melainkan oleh penghargaan terhadap yang telah diperoleh, dan menunjukkan bahwa syukur merupakan kepentingan manusia sendiri bukan kepentingan Allah karena Allah Mahakaya sehingga syukur dan kufur tidak menambah atau mengurangi kemuliaan-Nya'],answer:3,explanation:'Q.S. Ibrahim [14]: 7 berbunyi jika kalian bersyukur maka Aku menambah nikmat kepada kalian dan jika kalian kufur maka sesungguhnya azab-Ku sangat pedih. Q.S. an-Naml [27]: 40 berbunyi barangsiapa bersyukur maka syukurnya untuk dirinya sendiri dan barangsiapa kufur maka sesungguhnya Tuhanku Mahakaya lagi Mahamulia, yang menunjukkan bahwa syukur merupakan kepentingan manusia sendiri. Q.S. an-Nahl [16]: 18 berbunyi dan jika kalian menghitung nikmat Allah niscaya kalian tidak dapat menghitungnya. Q.S. al-Baqarah [2]: 152 memerintahkan mengingat Allah dan bersyukur. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik yaitu apabila memperoleh nikmat ia bersyukur maka itu baik baginya dan apabila tertimpa musibah ia bersabar maka itu baik baginya. Hadis juga menyebut bahwa kekayaan yang hakiki bukan banyaknya harta melainkan kekayaan jiwa. Adapun bertambahnya nikmat merupakan janji Allah tetapi tujuan utama syukur bukan kenyamanan dunia melainkan pengakuan terhadap pemberi nikmat, dan bersyukur bukan ibadah yang mudah karena sedikit sekali hamba yang bersyukur sebagaimana disebut dalam Q.S. Saba [34]: 13.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi teman yang menyakiti',text:'Perilaku sabar ketika menghadapi teman yang menyakiti yang paling tepat adalah ...',options:['tidak merespons sama sekali karena merespons merupakan tanda bahwa kesabarannya belum sempurna','menahan diri dari membalas dengan cara yang dilarang seperti mencela balik, menyebarkan keburukannya, atau membalas melalui media sosial, menahan amarah pada saat pertama karena menahan amarah merupakan sifat orang yang bertakwa dan memaafkan merupakan amal yang pahalanya atas Allah, menyelesaikan persoalan secara langsung dengan bahasa yang sopan apabila penyampaian itu dapat memperbaiki keadaan, memaafkan apabila memaafkan menghasilkan kebaikan yang lebih besar dan tidak mendorong pihak yang menyakiti mengulangi perbuatannya, menuntut hak melalui jalur yang benar apabila terdapat hak yang diambil dan tidak dapat diselesaikan secara kekeluargaan, serta mendoakan kebaikan bagi pihak yang menyakiti karena doa merupakan cara mengubah keadaan yang tidak terlihat oleh pihak lain','menahan diri dari membalas dengan cara yang dilarang dan menyelesaikan persoalan dengan cara yang baik','membalas dengan cara yang setimpal agar pihak yang menyakiti tidak mengulangi perbuatannya kepada orang lain'],answer:1,explanation:'Q.S. Ali Imran [3]: 134 menggambarkan orang yang bertakwa yaitu yang menafkahkan dalam keadaan lapang dan sempit serta menahan amarahnya dan memaafkan manusia, dan Allah menyukai orang-orang yang berbuat kebaikan. Q.S. asy-Syura [42]: 40 berbunyi balasan keburukan adalah keburukan yang serupa, maka barangsiapa memaafkan dan berbuat baik maka pahalanya atas Allah. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, sehingga menyampaikan keberatan secara langsung merupakan adab persaudaraan. Hadis juga menyebut bahwa tidak halal bagi seorang muslim mendiamkan saudaranya lebih dari tiga hari dan yang terbaik di antara keduanya adalah yang memulai salam. Hadis juga menganjurkan mendoakan kebaikan bagi orang lain tanpa kehadirannya karena doa itu mustajab. Q.S. asy-Syura [42]: 40 menyebut bahwa Allah tidak menyukai orang-orang yang zalim, sehingga membalas dengan cara yang melampaui batas bukan pilihan yang dibenarkan.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya istiqamah sebagai perintah yang berat',text:'Rasulullah menyatakan bahwa Q.S. Hud [11]: 112 dan surah-surah sejenisnya membuat beliau beruban. Analisis yang paling tepat terhadap hikmah beratnya perintah istiqamah tersebut adalah ...',options:['hikmahnya agar manusia memahami bahwa istiqamah bukan perintah yang ringan karena mencakup keteguhan dalam seluruh bidang kehidupan sepanjang hayat bukan hanya dalam ibadah yang bersifat waktu tertentu, dan hikmah itu juga menunjukkan bahwa menjaga keteguhan lebih berat daripada memulai karena memulai dapat dilakukan dengan semangat yang tinggi sedangkan menjaga memerlukan kesabaran ketika semangat menurun, serta menunjukkan bahwa istiqamah berkaitan dengan seluruh keadaan termasuk ketika tidak ada yang melihat dan ketika tidak ada yang menghargai sehingga merupakan ujian terhadap ketulusan niat, dan menunjukkan bahwa perintah itu disertai larangan melampaui batas sehingga istiqamah bukan berarti membebani diri melebihi kemampuan melainkan tetap berada di jalan yang benar sesuai kemampuan','hikmahnya karena istiqamah hanya dapat dicapai oleh para nabi sehingga manusia biasa perlu berusaha semampunya tanpa harapan mencapainya','hikmahnya agar manusia tidak merasa cukup dengan amal yang telah dikerjakan karena amal itu belum pasti diterima','hikmahnya agar manusia memahami bahwa istiqamah memerlukan kesungguhan yang berkelanjutan sepanjang hayat'],answer:0,explanation:'Q.S. Hud [11]: 112 berbunyi maka beristiqamahlah sebagaimana diperintahkan kepadamu dan kepada orang yang bertobat bersamamu serta janganlah melampaui batas, sesungguhnya Dia Maha Melihat apa yang kalian kerjakan. Hadis juga menyebut bahwa Rasulullah bersabda telah membuatku beruban Q.S. Hud dan surah-surah sejenisnya, yang menunjukkan beratnya perintah istiqamah. Q.S. Fussilat [41]: 30-31 menggambarkan keutamaan orang yang beristiqamah yaitu malaikat turun kepada mereka dengan mengatakan jangan takut dan jangan bersedih. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa agama ini mudah sehingga tidak ada orang yang mempersulit diri dalam agama melainkan agama itu mengalahkannya, yang sesuai dengan larangan melampaui batas. Adapun istiqamah dapat dicapai oleh orang beriman dengan pertolongan Allah sehingga bukan keadaan yang hanya dicapai oleh para nabi, dan merasa cukup dengan amal yang telah dikerjakan bukan maksud utama hikmah beratnya istiqamah.'},
{level:'HOTS',indicator:'Menentukan perilaku syukur ketika memperoleh nilai yang baik',text:'Perilaku syukur ketika memperoleh nilai yang baik yang paling tepat adalah ...',options:['merayakan keberhasilan dengan cara yang menyenangkan tanpa mempertimbangkan batas karena keberhasilan merupakan kesempatan yang jarang diperoleh','menunjukkan nilai kepada sebanyak mungkin orang agar usahanya diketahui dan dihargai','memuji Allah, tidak sombong, dan menggunakan kemampuan untuk memberi manfaat kepada teman','memuji Allah dengan menyadari bahwa kemampuan memahami dan kesempatan belajar merupakan karunia yang disertai usahanya, tidak sombong atas nilai yang diperoleh dan tidak merendahkan teman yang nilainya lebih rendah karena nilai bukan ukuran kemuliaan di sisi Allah, menggunakan kemampuan yang dimiliki untuk memberi manfaat seperti menjelaskan kepada teman yang belum memahami karena ilmu yang diajarkan menghasilkan pahala yang berkelanjutan, bersyukur dengan memperbanyak amal bukan dengan merayakan secara berlebihan atau dengan perbuatan yang melalaikan dari kewajiban, serta tidak menjadikan nilai sebagai alasan merasa cukup sehingga berhenti belajar karena nilai yang baik merupakan hasil dari proses yang perlu dilanjutkan'],answer:3,explanation:'Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Q.S. an-Nahl [16]: 53 berbunyi dan apa pun nikmat yang ada pada kalian maka dari Allah. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Q.S. an-Najm [53]: 32 melarang menyebut diri sendiri suci karena Allah paling mengetahui tentang orang yang bertakwa. Hadis juga menyebut bahwa sombong adalah menolak kebenaran dan meremehkan manusia. Q.S. ad-Duha [93]: 11 berbunyi dan terhadap nikmat Tuhanmu hendaklah engkau menyebut-nyebutnya, dalam pengertian mengakui dan mensyukuri bukan membanggakan. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga belajar tetap dilanjutkan setelah memperoleh nilai yang baik. Adapun merayakan secara berlebihan atau tanpa batas merupakan bentuk melampaui batas yang dilarang sebagaimana Q.S. al-Araf [7]: 31.'},
{level:'HOTS',indicator:'Menganalisis hubungan sabar dengan syukur',text:'Sabar dan syukur disebut sebagai dua sikap yang menyertai seluruh keadaan orang beriman. Analisis yang paling tepat terhadap hubungan keduanya adalah ...',options:['hubungan itu berarti sabar lebih utama daripada syukur karena musibah lebih sering terjadi daripada nikmat','hubungan itu menunjukkan bahwa syukur diperlukan ketika memperoleh nikmat yang besar sedangkan sabar diperlukan ketika menghadapi musibah yang berat saja','hubungan itu menunjukkan bahwa seluruh keadaan yang dihadapi oleh orang beriman menghasilkan kebaikan baginya yaitu apabila memperoleh nikmat ia bersyukur maka syukur itu baik baginya dan apabila tertimpa musibah ia bersabar maka kesabaran itu baik baginya, dan hal itu tidak diperoleh oleh selain orang mukmin karena orang yang tidak beriman ketika memperoleh nikmat cenderung sombong dan ketika tertimpa musibah cenderung berputus asa atau menyalahkan keadaan, dan hubungan itu juga menunjukkan bahwa kedua sikap itu saling melengkapi karena syukur tanpa sabar menghasilkan kesedihan yang berlebihan ketika nikmat dicabut sedangkan sabar tanpa syukur menghasilkan kepasrahan yang kehilangan penghargaan terhadap nikmat yang masih ada, serta menunjukkan bahwa kedua sikap itu merupakan bukti keimanan kepada takdir karena keduanya lahir dari keyakinan bahwa seluruh yang terjadi berasal dari Allah dan mengandung hikmah','hubungan itu menunjukkan bahwa orang beriman selalu berada dalam kebaikan karena memperoleh nikmat lalu bersyukur atau tertimpa musibah lalu bersabar'],answer:2,explanation:'Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik dan hal itu tidak diperoleh oleh selain orang mukmin yaitu apabila memperoleh nikmat ia bersyukur maka itu baik baginya dan apabila tertimpa musibah ia bersabar maka itu baik baginya. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar disempurnakan pahalanya tanpa perhitungan. Q.S. al-Hadid [57]: 22-23 menyebut agar tidak bersedih atas apa yang luput dan tidak gembira berlebihan atas apa yang diberikan. Hadis Jibril juga menyebut bahwa beriman kepada takdir yang baik dan yang buruk merupakan rukun iman. Q.S. Saba [34]: 13 menyebut bahwa sedikit sekali dari hamba-hamba-Ku yang bersyukur. Adapun tidak dinyatakan bahwa sabar lebih utama daripada syukur secara mutlak karena keduanya memiliki kedudukan yang berbeda dalam keadaan yang berbeda, dan keduanya diperlukan dalam keadaan yang kecil maupun yang besar bukan hanya dalam keadaan yang besar.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam menjaga salat berjamaah',text:'Perilaku istiqamah dalam menjaga salat berjamaah yang paling tepat adalah ...',options:['melaksanakan salat berjamaah di masjid secara teratur pada waktu-waktu yang memungkinkan walaupun keadaannya tidak selalu mendukung seperti ketika cuaca tidak bersahabat atau ketika sedang lelah, tidak menjadikan kegiatan lain sebagai alasan meninggalkan salat berjamaah selama kegiatan itu bukan uzur yang dibenarkan, mengatur jadwal kegiatan sehingga tidak bertabrakan dengan waktu salat karena pengaturan waktu merupakan bagian dari kesungguhan menjaga ibadah, melaksanakan salat pada waktunya dengan khusyuk dan tidak tergesa-gesa walaupun berjamaah bersama orang yang salat dengan cepat, serta tidak merasa cukup dengan melaksanakan salat berjamaah pada waktu tertentu saja seperti salat Jumat atau salat hari raya karena istiqamah berarti keteraturan bukan kekhususan pada waktu tertentu','menjaga salat berjamaah pada waktu Subuh saja karena salat Subuh berjamaah paling berat sehingga paling utama','menjaga salat berjamaah secara teratur walaupun keadaannya tidak selalu mendukung','melaksanakan salat berjamaah sebanyak mungkin dalam satu waktu lalu mengurangi pada waktu lain agar tidak merasa terbebani'],answer:0,explanation:'Q.S. al-Baqarah [2]: 43 berbunyi dan dirikanlah salat serta tunaikanlah zakat dan rukuklah bersama orang-orang yang rukuk. Hadis juga menyebut bahwa salat berjamaah lebih utama daripada salat sendirian dengan dua puluh tujuh derajat. Hadis juga menyebut bahwa salat yang paling berat bagi orang munafik adalah salat Isya dan salat Subuh, dan seandainya mereka mengetahui keutamaannya niscaya mereka mendatanginya walaupun dengan merangkak. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Muminun [23]: 2 menyebut ciri orang beriman yang khusyuk dalam salatnya. Hadis juga menyebut bahwa orang yang paling buruk pencuriannya adalah yang mencuri dalam salatnya yaitu yang tidak menyempurnakan rukuk dan sujudnya. Q.S. Fussilat [41]: 30 menggambarkan keutamaan orang yang beristiqamah. Adapun menjaga salat berjamaah tidak terbatas pada waktu Subuh karena seluruh waktu salat memiliki keutamaan berjamaah, dan melaksanakan sebanyak mungkin dalam satu waktu lalu mengurangi bukan bentuk istiqamah.'},
{level:'HOTS',indicator:'Menganalisis hikmah dianjurkannya berbaik sangka kepada Allah',text:'Berbaik sangka kepada Allah dianjurkan bahkan ketika menghadapi kematian. Analisis yang paling tepat terhadap hikmah anjuran tersebut adalah ...',options:['hikmahnya agar manusia menghadapi ketentuan Allah dengan hati yang tenang karena meyakini bahwa Allah menetapkan berdasarkan ilmu yang sempurna dan rahmat yang luas sehingga ketentuan yang tidak sesuai keinginan tetap mengandung hikmah, dan hikmah itu juga agar manusia tidak berputus asa dari rahmat Allah ketika menghadapi dosa atau kesulitan karena berputus asa merupakan bentuk buruk sangka yang menjauhkan dari tobat, serta agar manusia menghadapi kematian dengan harapan kepada Allah sehingga tidak dikuasai oleh ketakutan yang melumpuhkan, dan menunjukkan bahwa berbaik sangka kepada Allah perlu disertai amal karena baik sangka tanpa amal merupakan angan-angan yang menipu','hikmahnya karena baik sangka kepada Allah menghasilkan pengabulan seluruh keinginan sehingga yang diinginkan pasti diperoleh','hikmahnya agar manusia merasa aman dari azab Allah karena Allah Maha Pengampun','hikmahnya agar manusia menghadapi ketentuan Allah dengan hati yang tenang dan tidak berputus asa dari rahmat-Nya'],answer:0,explanation:'Hadis qudsi juga menyebut bahwa Aku sesuai dengan persangkaan hamba-Ku terhadap-Ku, maka hendaklah ia menyangka apa yang ia kehendaki. Hadis juga menyebut bahwa janganlah seorang di antara kalian wafat melainkan dalam keadaan berbaik sangka kepada Allah. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Q.S. al-Fath [48]: 6 mengecam orang yang berburuk sangka kepada Allah dan menyebut bahwa bagi mereka giliran keburukan. Q.S. al-Araf [7]: 99 menyebut pertanyaan apakah mereka merasa aman dari rencana Allah sehingga tidak ada yang merasa aman dari rencana Allah kecuali orang-orang yang merugi, yang menunjukkan bahwa merasa aman dari azab bukan hasil baik sangka yang benar. Q.S. az-Zumar [39]: 53 melarang berputus asa dari rahmat Allah dan menyebut bahwa Allah mengampuni dosa-dosa semuanya. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga baik sangka perlu disertai amal.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menghadapi kegagalan yang berulang',text:'Perilaku sabar ketika menghadapi kegagalan yang berulang yang paling tepat adalah ...',options:['berhenti berusaha karena kegagalan yang berulang menunjukkan bahwa jalan itu tidak ditetapkan untuknya','tetap berusaha sambil mengevaluasi cara yang digunakan dan tidak kehilangan harapan','tetap berusaha karena kegagalan yang berulang bukan tanda bahwa usaha itu tidak akan berhasil melainkan tanda bahwa cara yang digunakan perlu diperbaiki, mengevaluasi cara yang digunakan dengan jujur untuk mengetahui bagian yang menjadi sebab kegagalan sehingga evaluasi itu bukan sekadar mengulang cara yang sama dengan harapan hasil yang berbeda, meminta pertimbangan kepada pihak yang berpengalaman karena pertimbangan dari pihak luar sering melihat hal yang tidak terlihat oleh pihak yang mengalami, tidak kehilangan harapan karena berputus asa dari rahmat Allah merupakan sikap yang dilarang dan karena keberhasilan dapat datang setelah kegagalan yang terakhir, tidak menyalahkan pihak lain atas kegagalan yang berulang karena menyalahkan pihak lain menghindari tanggung jawab atas evaluasi yang perlu dilakukan, serta memohon pertolongan kepada Allah melalui doa dan istikharah agar ditunjukkan jalan yang lebih baik','mengulang usaha dengan cara yang sama secara terus-menerus karena ketekunan menghasilkan keberhasilan walaupun caranya tidak diubah'],answer:2,explanation:'Q.S. al-Insyirah [94]: 5-6 berbunyi bersama kesulitan terdapat kemudahan. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah, dan menganjurkan berusaha serta meminta pertolongan kepada Allah dan tidak lemah. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Hadis juga melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Hadis menganjurkan istikharah dan menyebut bahwa orang yang beristikharah tidak akan kecewa dan orang yang bermusyawarah tidak akan menyesal. Q.S. ar-Rad [13]: 11 berbunyi sesungguhnya Allah tidak mengubah keadaan suatu kaum sehingga mereka mengubah keadaan yang ada pada diri mereka sendiri, yang menunjukkan bahwa perubahan cara merupakan bagian dari perubahan keadaan. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, tetapi keberlanjutan itu perlu disertai perbaikan cara karena mengulang cara yang sama tanpa perubahan bukan ketekunan yang menghasilkan perbaikan.'},
{level:'HOTS',indicator:'Menganalisis bahaya kufur nikmat',text:'Kufur nikmat merupakan lawan dari syukur dan diancam dengan azab yang pedih. Analisis yang paling tepat terhadap bahaya kufur nikmat adalah ...',options:['bahayanya meliputi kemungkinan dicabutnya nikmat karena Allah mengancam orang yang kufur dengan azab yang pedih dan nikmat yang tidak disyukuri merupakan nikmat yang terancam hilang, bahayanya juga bahwa kufur nikmat menjadikan manusia lalai dari pemberi nikmat sehingga nikmat itu tidak mendekatkannya kepada Allah melainkan menjauhkannya karena ia semakin terikat pada nikmat bukan pada pemberinya, serta bahayanya bahwa kufur nikmat sering menghasilkan penggunaan nikmat untuk bermaksiat sehingga nikmat itu berubah menjadi sebab azab bukan sebab pahala, dan menunjukkan bahwa kufur nikmat tidak selalu berarti mengingkari adanya nikmat melainkan dapat berupa tidak menggunakan nikmat sesuai dengan tujuan pemberiannya','bahayanya bahwa nikmat yang tidak disyukuri dapat dicabut dan menghasilkan azab serta menjadikan manusia lalai dari pemberi nikmat','bahayanya bahwa orang yang kufur nikmat keluar dari Islam sehingga seluruh amalnya terhapus','bahayanya hanya berlaku bagi nikmat yang besar sedangkan nikmat yang kecil tidak menimbulkan akibat apabila tidak disyukuri'],answer:0,explanation:'Q.S. Ibrahim [14]: 7 berbunyi jika kalian bersyukur maka Aku menambah nikmat kepada kalian dan jika kalian kufur maka sesungguhnya azab-Ku sangat pedih. Q.S. an-Nahl [16]: 112 menggambarkan suatu negeri yang dahulu aman dan tenteram yang rezekinya melimpah dari segala tempat lalu penduduknya mengingkari nikmat Allah sehingga Allah merasakan kepada mereka kelaparan dan ketakutan karena apa yang telah mereka perbuat. Q.S. al-Qasas [28]: 78 menggambarkan Qarun yang mengira hartanya merupakan hasil ilmunya lalu Allah membenamkannya beserta rumahnya. Hadis juga menyebut bahwa kekayaan yang hakiki bukan banyaknya harta melainkan kekayaan jiwa. Q.S. al-Baqarah [2]: 152 memerintahkan bersyukur dan melarang kufur. Adapun kufur nikmat tidak selalu mengeluarkan dari Islam karena mengingkari nikmat dengan tidak bersyukur merupakan dosa besar sedangkan keluar dari Islam terjadi apabila mengingkari adanya Allah sebagai pemberi nikmat dengan keyakinan yang menolak-Nya, dan nikmat yang kecil juga perlu disyukuri karena seluruh nikmat berasal dari Allah dan tidak dapat dihitung.'},
{level:'HOTS',indicator:'Menentukan perilaku husnuzan ketika menerima informasi buruk tentang teman',text:'Perilaku husnuzan ketika menerima informasi buruk tentang teman yang paling tepat adalah ...',options:['langsung menegur teman itu di depan orang lain agar ia segera menyadari kesalahannya dan tidak mengulangi','tidak segera membenarkan informasi itu dan tidak segera menyalahkannya melainkan meneliti kebenarannya melalui sumber yang dapat dipercaya karena meneliti berita merupakan perintah agama, tidak menyebarkan informasi itu kepada pihak lain sebelum jelas kebenarannya karena menyebarkan informasi yang belum diteliti dapat merugikan pihak yang diberitakan dan menjadikan penyebarnya turut bertanggung jawab atas keburukan yang timbul, mencari kemungkinan penjelasan yang baik atas perbuatan yang diberitakan karena terdapat kemungkinan bahwa perbuatan itu memiliki penjelasan yang tidak diketahui oleh penyampai berita, menasihati teman secara langsung dengan cara yang baik apabila informasi itu ternyata benar agar ia memperbaiki keadaannya, serta tidak menggunjing teman itu dengan pihak lain karena menggunjing merupakan dosa tersendiri walaupun informasinya benar','tidak segera membenarkan informasi itu dan menelitinya sebelum mengambil sikap','menyimpan informasi itu dan memutuskan hubungan dengan teman itu agar tidak terpengaruh oleh keburukannya'],answer:1,explanation:'Q.S. al-Hujurat [49]: 6 berbunyi jika datang kepada kalian orang fasik membawa suatu berita maka telitilah kebenarannya agar kalian tidak mencelakakan suatu kaum karena kebodohan. Q.S. an-Nur [24]: 12 menegur orang beriman yang tidak berbaik sangka ketika mendengar berita bohong. Q.S. al-Hujurat [49]: 12 melarang ghibah dan menggambarkannya seperti memakan daging saudaranya yang telah mati. Hadis juga menyebut bahwa cukuplah seseorang dikatakan berdusta apabila ia menceritakan segala yang didengarnya. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, sehingga menasihati secara langsung merupakan adab persaudaraan. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya. Adapun menegur di depan orang lain mempermalukan pihak yang ditegur dan tidak menghasilkan perbaikan, dan memutuskan hubungan tanpa klarifikasi merupakan bentuk buruk sangka yang dilarang serta memutus silaturahmi yang diperintahkan.'},
{level:'HOTS',indicator:'Menganalisis hikmah diperintahkannya sabar ketika menghadapi musibah',text:'Sabar diperintahkan ketika menghadapi musibah. Analisis yang paling tepat terhadap hikmah perintah tersebut adalah ...',options:['hikmahnya agar musibah cepat berakhir karena kesabaran mempercepat datangnya jalan keluar','hikmahnya karena sabar merupakan satu-satunya sikap yang tersedia ketika menghadapi musibah sehingga tidak ada pilihan lain','hikmahnya agar musibah menghasilkan pahala bagi orang yang menghadapinya dengan sabar dan tidak menghasilkan dosa tambahan karena keluhan yang menunjukkan ketidakrelaan terhadap ketentuan Allah merupakan dosa yang menambah penderitaan, dan hikmah itu juga agar musibah menghasilkan pembersihan kesalahan karena musibah menghapus sebagian kesalahan orang yang bersabar sehingga musibah berubah dari kerugian menjadi keuntungan, serta agar musibah menghasilkan kedewasaan jiwa karena menghadapi kesulitan dengan sabar melatih kemampuan menghadapi kesulitan berikutnya, dan menunjukkan bahwa sabar bukan berarti tidak berusaha mengatasi musibah karena berusaha mengatasi merupakan bagian dari kesabaran yang diperintahkan','hikmahnya agar musibah menghasilkan pahala dan tidak menghasilkan dosa tambahan'],answer:2,explanation:'Q.S. al-Baqarah [2]: 155-156 berbunyi dan sungguh Kami akan menguji kalian dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa, dan buah-buahan, dan sampaikanlah kabar gembira kepada orang-orang yang sabar yaitu orang-orang yang apabila tertimpa musibah mereka mengucapkan sesungguhnya kami milik Allah dan kepada-Nya kami kembali. Hadis juga menyebut bahwa tidaklah seorang muslim tertimpa kelelahan, penyakit, kesedihan, kesusahan, gangguan, dan gundah gulana bahkan duri yang menusuknya melainkan Allah menghapus sebagian kesalahannya. Hadis juga menyebut bahwa kesabaran itu pada hentakan pertama. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar disempurnakan pahalanya tanpa perhitungan. Hadis juga menyebut kisah Umar yang tidak jadi memasuki wilayah yang terkena wabah dan menjawab kami lari dari takdir Allah menuju takdir Allah yang lain, yang menunjukkan bahwa berusaha mengatasi musibah merupakan bagian dari kesabaran. Adapun kesabaran tidak selalu mempercepat berakhirnya musibah karena waktu berakhirnya merupakan ketentuan Allah, dan sabar bukan satu-satunya sikap yang tersedia karena manusia juga diperintahkan berusaha dan berdoa.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam menjaga akhlak ketika berada di lingkungan yang tidak mendukung',text:'Perilaku istiqamah dalam menjaga akhlak ketika berada di lingkungan yang tidak mendukung yang paling tepat adalah ...',options:['tetap menjaga akhlak dan tidak mengikuti kebiasaan lingkungan yang bertentangan dengan ketentuan agama','tetap menjaga akhlak walaupun lingkungan sekitarnya tidak mendukung karena nilai akhlak tidak ditentukan oleh kebiasaan lingkungan melainkan oleh ketentuan agama, tidak mengikuti kebiasaan lingkungan yang bertentangan dengan ketentuan agama walaupun mengikuti itu menghasilkan penerimaan dari lingkungan karena penerimaan lingkungan tidak sebanding dengan akibat yang ditimbulkan, memilih pergaulan yang mendukung dalam kebaikan karena pergaulan berpengaruh besar terhadap pembentukan kebiasaan sehingga mengurangi waktu bersama pihak yang mendorong kepada keburukan bukan bentuk memutus silaturahmi melainkan bentuk menjaga diri, tetap berbuat baik kepada lingkungan yang tidak mendukung dengan cara yang tidak mengorbankan akidah dan akhlak karena berbuat baik dapat menjadi teladan yang mengubah lingkungan, serta memohon pertolongan kepada Allah agar dijaga dari pengaruh lingkungan yang buruk','meninggalkan lingkungan itu sepenuhnya karena lingkungan yang tidak mendukung tidak dapat diubah','mengikuti kebiasaan lingkungan untuk sementara agar diterima lalu mengubah kebiasaan itu dari dalam setelah memperoleh kedudukan'],answer:1,explanation:'Hadis juga menyebut bahwa agama seseorang mengikuti agama sahabat karibnya sehingga hendaklah memperhatikan siapa yang dijadikan sahabat karibnya. Hadis juga menyebut bahwa perumpamaan teman yang baik dan teman yang buruk seperti penjual minyak wangi dan pandai besi. Hadis juga menyebut bahwa barangsiapa di antara kalian melihat kemungkaran hendaklah mengubahnya dengan tangan, dengan lisan, atau dengan hati, dan yang demikian itu merupakan selemah-lemah iman. Q.S. al-Anam [6]: 68 melarang duduk bersama orang yang memperolok-olok ayat Allah hingga mereka berpindah kepada pembicaraan yang lain. Q.S. al-Mumtahanah [60]: 8 menyebut bahwa Allah tidak melarang berbuat baik dan berlaku adil terhadap orang yang tidak memerangi karena agama. Hadis juga menganjurkan doa memohon keteguhan hati. Adapun mengikuti kebiasaan lingkungan yang bertentangan dengan ketentuan agama dengan alasan mengubahnya dari dalam bukan cara yang dibenarkan karena mengikuti yang dilarang merupakan dosa, dan meninggalkan lingkungan sepenuhnya bukan satu-satunya pilihan karena menjaga diri dapat dilakukan dengan mengurangi waktu bersama tanpa memutus silaturahmi.'},
{level:'HOTS',indicator:'Menganalisis kedudukan syukur dalam menghadapi nikmat yang tampak kecil',text:'Nikmat yang tampak kecil seperti kesehatan dan waktu luang disebut sebagai nikmat yang banyak manusia tertipu di dalamnya. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu berarti nikmat yang kecil tidak perlu disyukuri karena yang perlu disyukuri hanya nikmat yang besar','kedudukan itu menunjukkan bahwa nikmat yang paling besar sering tidak disadari karena kehadirannya terus-menerus dan kehilangannya tidak segera terasa, sehingga kesehatan dan waktu luang merupakan nikmat yang paling sering disia-siakan karena manusia menggunakannya untuk hal yang tidak menghasilkan manfaat bagi dunia maupun akhiratnya, dan kedudukan itu juga menunjukkan bahwa bersyukur atas nikmat yang tampak kecil merupakan latihan untuk bersyukur atas nikmat yang besar karena orang yang tidak menghargai yang kecil cenderung tidak menghargai yang besar, serta menunjukkan bahwa memperhatikan nikmat yang kecil menghasilkan kesadaran bahwa jumlah nikmat tidak dapat dihitung sehingga menghasilkan kerendahan hati di hadapan pemberi nikmat','kedudukan itu menunjukkan bahwa kesehatan dan waktu luang bukan nikmat melainkan keadaan biasa sehingga tidak menghasilkan pahala apabila disyukuri','kedudukan itu menunjukkan bahwa nikmat yang paling besar sering tidak disadari sehingga perlu diperhatikan secara khusus'],answer:1,explanation:'Hadis juga menyebut bahwa dua nikmat yang banyak manusia tertipu di dalamnya yaitu kesehatan dan waktu luang. Q.S. an-Nahl [16]: 18 berbunyi dan jika kalian menghitung nikmat Allah niscaya kalian tidak dapat menghitungnya, sesungguhnya Allah Maha Pengampun lagi Maha Penyayang. Q.S. al-Asr [103]: 1-3 menyebut kerugian manusia kecuali yang beriman dan beramal saleh. Hadis juga menyebut bahwa tidak akan bergeser kedua kaki seorang hamba pada hari kiamat hingga ditanya tentang umurnya untuk apa dihabiskan. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga menyebut bahwa lindungilah diri kalian dari api neraka walaupun dengan separuh butir kurma, yang menunjukkan bahwa yang kecil tetap bernilai. Adapun nikmat yang kecil tetap perlu disyukuri karena seluruh nikmat berasal dari Allah dan tidak dapat dihitung, dan kesehatan serta waktu luang merupakan nikmat yang besar yang akan dimintai pertanggungjawabannya sehingga mensyukurinya menghasilkan pahala.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dalam menuntut ilmu',text:'Perilaku sabar dalam menuntut ilmu yang paling tepat adalah ...',options:['belajar dengan cara yang paling cepat walaupun tidak memahami karena yang dinilai adalah hasil ujian bukan proses pemahaman','tetap belajar walaupun terasa berat karena memahami ilmu memerlukan waktu dan pengulangan sehingga hasil yang diharapkan tidak selalu segera tercapai, tidak berhenti belajar karena memperoleh nilai yang kurang baik karena nilai yang kurang baik merupakan informasi tentang bagian yang perlu diperbaiki bukan tanda bahwa ia tidak mampu, bersabar terhadap cara mengajar yang tidak sesuai dengan keinginannya dengan tetap mengambil manfaat dari penjelasan yang diberikan dan melengkapi sendiri bagian yang belum dipahami, tidak membandingkan kecepatannya memahami dengan kecepatan teman karena perbandingan itu menghasilkan putus asa atau sombong yang keduanya mengganggu proses belajar, mengatur waktu belajar secara teratur karena keteraturan menghasilkan kemajuan yang berkelanjutan walaupun sedikit, serta bersyukur atas kesempatan belajar karena kesempatan itu merupakan nikmat yang tidak dimiliki oleh seluruh orang','belajar hanya ketika merasa mampu memahami karena belajar dalam keadaan tidak mampu hanya menghasilkan kelelahan','tetap belajar walaupun terasa berat dan tidak segera memperoleh hasil yang diharapkan'],answer:1,explanation:'Hadis juga menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah mudahkan baginya jalan menuju surga. Hadis juga menyebut bahwa ilmu tidak diperoleh kecuali dengan kesabaran dan tawadu. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. az-Zumar [39]: 9 menyebut apakah sama orang yang mengetahui dengan orang yang tidak mengetahui. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian, sehingga membandingkan kemampuan bukan ukuran kemuliaan. Hadis juga menyebut bahwa barangsiapa menipu maka ia bukan dari golongan Rasulullah, sehingga belajar dengan cara yang paling cepat tanpa memahami merupakan bentuk menipu diri sendiri dan menipu pihak yang menilai.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya husnuzan sebagai bagian dari ibadah yang baik',text:'Husnuzan disebut sebagai bagian dari ibadah yang baik. Analisis yang paling tepat terhadap hikmah sebutan tersebut adalah ...',options:['hikmahnya karena husnuzan menghasilkan keuntungan dalam urusan dunia sehingga pihak yang berhusnuzan lebih dipercaya dalam berbisnis','hikmahnya agar manusia memahami bahwa penghambaan kepada Allah tidak terbatas pada ibadah yang bersifat ritual melainkan meliputi sikap hati terhadap sesama manusia karena menahan diri dari menilai buruk tanpa dasar merupakan bentuk ketaatan terhadap perintah Allah, dan hikmah itu juga menunjukkan bahwa husnuzan menghasilkan kebersihan hati dari penyakit dengki, curiga, dan permusuhan yang menghabiskan energi jiwa tanpa menghasilkan manfaat, serta menunjukkan bahwa husnuzan merupakan bentuk mengikuti cara Allah dalam menilai hamba-Nya karena Allah menutupi kekurangan hamba-Nya dan menerima tobatnya sehingga manusia yang berhusnuzan meneladani sifat itu dalam batas yang dibolehkan, dan menunjukkan bahwa husnuzan menghasilkan hubungan sosial yang lebih baik karena pihak yang diperlakukan dengan baik sangka cenderung membalas dengan sikap yang baik','hikmahnya agar manusia tidak menilai orang lain sama sekali karena menilai merupakan hak Allah','hikmahnya agar manusia memahami bahwa sikap hati terhadap sesama merupakan bagian dari penghambaan kepada Allah'],answer:1,explanation:'Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Q.S. al-Hujurat [49]: 12 berbunyi jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa. Hadis qudsi juga menyebut bahwa Aku sesuai dengan persangkaan hamba-Ku terhadap-Ku. Q.S. al-Hasyr [59]: 9 menggambarkan kaum Ansar yang tidak menaruh keinginan dalam hati mereka terhadap apa yang diberikan kepada kaum Muhajirin, yang menunjukkan kebersihan hati dari dengki. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya. Hadis juga menyebut bahwa Allah Maha Penyayang dan menutupi kekurangan hamba-Nya serta menerima tobatnya. Adapun husnuzan tidak berarti meninggalkan penilaian yang diperlukan karena kewaspadaan dan verifikasi tetap diperintahkan, dan keuntungan dalam urusan dunia bukan hikmah utama husnuzan karena hikmah utamanya berkaitan dengan kebersihan hati dan ketaatan kepada Allah.'},
{level:'HOTS',indicator:'Menentukan perilaku syukur ketika menghadapi keadaan yang tidak sesuai keinginan',text:'Perilaku syukur ketika menghadapi keadaan yang tidak sesuai keinginan yang paling tepat adalah ...',options:['tetap bersyukur atas nikmat yang masih ada dan bersabar atas keadaan yang tidak diinginkan','mengeluhkan keadaannya kepada orang lain agar memperoleh dukungan dan doa dari mereka karena dukungan membantu menghadapi kesulitan','tetap bersyukur atas nikmat yang masih ada karena keadaan yang tidak sesuai keinginan tidak menghilangkan seluruh nikmat sehingga memperhatikan nikmat yang tersisa merupakan cara menjaga syukur, bersabar atas keadaan yang tidak diinginkan dengan meyakini bahwa keadaan itu mengandung hikmah yang belum diketahui dan bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik baginya, tidak mengucapkan keluhan yang menunjukkan ketidakrelaan terhadap ketentuan Allah karena keluhan itu mengurangi pahala kesabaran, membandingkan keadaannya dengan keadaan orang yang lebih sulit agar memperoleh kesadaran bahwa keadaannya masih lebih baik, berusaha mengubah keadaan yang dapat diubah karena syukur dan sabar bukan alasan meninggalkan usaha, serta berdoa memohon ganti yang lebih baik karena Allah menjanjikan ganti yang lebih baik bagi orang yang kehilangan sesuatu lalu mengucapkan kalimat istirja','tidak bersyukur karena bersyukur dalam keadaan yang tidak sesuai keinginan merupakan bentuk kepura-puraan'],answer:2,explanation:'Q.S. al-Baqarah [2]: 216 berbunyi boleh jadi kalian membenci sesuatu padahal sesuatu itu baik bagi kalian dan boleh jadi kalian menyukai sesuatu padahal sesuatu itu buruk bagi kalian, dan Allah mengetahui sedangkan kalian tidak mengetahui. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik yaitu apabila memperoleh nikmat ia bersyukur dan apabila tertimpa musibah ia bersabar. Hadis juga menyebut bahwa tidaklah seorang muslim tertimpa musibah lalu ia mengucapkan kalimat istirja dan berdoa memohon pengganti yang lebih baik melainkan Allah memberinya pengganti yang lebih baik. Hadis juga menyebut bahwa lihatlah orang yang di bawah kalian dan jangan melihat orang yang di atas kalian karena yang demikian lebih layak agar kalian tidak meremehkan nikmat Allah. Hadis juga melarang mengeluh kepada manusia dan menyebut bahwa orang yang mengadukan kesedihannya kepada manusia tidak tergolong orang yang sabar, tetapi mengadukan kepada Allah merupakan sunah para nabi sebagaimana Q.S. Yusuf [12]: 86. Hadis juga menganjurkan ikatlah untamu lalu bertawakallah.'},
{level:'HOTS',indicator:'Menganalisis cara menjaga istiqamah dalam berakhlak baik kepada orang tua',text:'Berakhlak baik kepada orang tua diperintahkan secara berkelanjutan. Analisis yang paling tepat terhadap cara menjaga istiqamah dalam akhlak tersebut adalah ...',options:['menjaga akhlak baik kepada orang tua hanya ketika keduanya memerlukan bantuan agar bantuannya terasa bernilai','menjaga adab kepada orang tua dalam seluruh keadaan termasuk ketika pendapatnya berbeda karena perbedaan pendapat bukan alasan mengurangi penghormatan, menyampaikan keberatan dengan bahasa yang sopan dan tidak meninggikan suara karena meninggikan suara di hadapan orang tua merupakan bentuk mengurangi penghormatan, tetap menaati keduanya dalam hal yang baik dan menolak dengan sopan apabila keduanya memerintahkan hal yang bertentangan dengan ketentuan agama sambil tetap berbuat baik kepada keduanya, memperhatikan keperluan keduanya secara berkala dan tidak menunggu hingga keduanya meminta karena meminta merupakan beban bagi pihak yang meminta, mendoakan keduanya secara teratur dan menyambung hubungan dengan kerabat serta sahabat keduanya, serta tidak mengurangi akhlak baik kepada keduanya ketika telah memperoleh kedudukan atau penghasilan sendiri karena kedudukan tidak mengubah hak orang tua','menjaga adab kepada orang tua dalam seluruh keadaan termasuk ketika pendapatnya berbeda dengan pendapatnya sendiri','menuruti seluruh keinginan orang tua walaupun keinginannya bertentangan dengan ketentuan agama karena menuruti merupakan bentuk bakti'],answer:1,explanation:'Q.S. al-Isra [17]: 23-24 berbunyi dan Tuhanmu telah memerintahkan agar kalian jangan menyembah selain Dia dan hendaklah berbuat baik kepada orang tua, dan jika salah seorang di antara keduanya atau kedua-duanya sampai berusia lanjut dalam pemeliharaanmu maka sekali-kali janganlah engkau mengatakan kepada keduanya perkataan ah dan janganlah engkau membentak keduanya serta ucapkanlah kepada keduanya perkataan yang mulia, dan rendahkanlah dirimu terhadap keduanya dengan penuh kasih sayang serta ucapkanlah wahai Tuhanku kasihilah keduanya sebagaimana keduanya mendidik aku ketika kecil. Q.S. Luqman [31]: 15 berbunyi jika keduanya memaksamu untuk mempersekutukan Aku maka janganlah engkau mengikuti keduanya dan pergaulilah keduanya di dunia dengan baik. Hadis juga menyebut bahwa ridha Allah berada pada ridha orang tua. Hadis juga menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya. Hadis juga menyebut bahwa bentuk bakti setelah orang tua wafat termasuk mendoakan keduanya dan memuliakan sahabat keduanya. Adapun menuruti keinginan orang tua yang bertentangan dengan ketentuan agama bukan bentuk bakti karena tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Allah, dan menjaga akhlak hanya ketika keduanya memerlukan bantuan bukan istiqamah karena istiqamah berarti keteraturan dalam seluruh keadaan.'},
{level:'HOTS',indicator:'Menentukan perilaku husnuzan ketika melihat teman tidak melaksanakan kewajiban',text:'Perilaku husnuzan ketika melihat teman tidak melaksanakan kewajiban yang paling tepat adalah ...',options:['tidak segera menilai buruk dan mengingatkan dengan cara yang baik serta pribadi','tidak segera menilai buruk keadaannya karena boleh jadi ia memiliki uzur yang tidak diketahui atau belum memahami kewajibannya, mengingatkan dengan cara yang baik dan secara pribadi karena mengingatkan di depan orang lain mempermalukan pihak yang diingatkan dan menghasilkan penolakan bukan perbaikan, tidak menyebarkan keadaan teman itu kepada pihak lain karena menyebarkan merupakan bentuk ghibah walaupun keadaannya benar, tetap menjaga hubungan persaudaraan dengannya karena meninggalkan kewajiban tertentu tidak menghalangi hak persaudaraan selama ia tidak meninggalkan keimanan, mengambil pelajaran dari keadaan teman itu dengan memeriksa dirinya sendiri apakah ia juga memiliki kekurangan yang serupa, serta mendoakan kebaikan baginya agar memperoleh petunjuk dan kemudahan dalam melaksanakan kewajiban','langsung menegur dengan tegas agar teman itu segera menyadari kewajibannya karena menunda teguran berarti membiarkan kemungkaran','tidak mengingatkan sama sekali karena mengingatkan merupakan bentuk menilai bahwa diri sendiri lebih baik daripadanya'],answer:1,explanation:'Q.S. al-Hujurat [49]: 12 berbunyi jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa. Hadis juga menyebut bahwa barangsiapa di antara kalian melihat kemungkaran hendaklah mengubahnya dengan tangan, dengan lisan, atau dengan hati. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, yang berarti mengingatkan merupakan bentuk kepedulian. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya dan tidaklah kekasaran ada pada sesuatu melainkan ia merusaknya. Q.S. al-Hujurat [49]: 12 melarang ghibah. Hadis juga menganjurkan mendoakan kebaikan bagi orang lain tanpa kehadirannya karena doa itu mustajab. Hadis juga menyebut bahwa seorang muslim adalah saudara bagi muslim yang lain sehingga tidak menzaliminya dan tidak menyerahkannya kepada musuh. Adapun tidak mengingatkan sama sekali bukan kerendahan hati yang benar melainkan bentuk membiarkan kemungkaran yang mengurangi iman, dan menegur dengan tegas dibolehkan dalam keadaan tertentu tetapi mengingatkan secara pribadi dengan kelembutan lebih sering menghasilkan perbaikan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa Allah bersama orang yang sabar',text:'Q.S. al-Baqarah [2]: 153 menyebut bahwa Allah bersama orang-orang yang sabar. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya agar orang yang bersabar memperoleh seluruh yang diinginkannya karena kebersamaan Allah menjamin pengabulan keinginan','hikmahnya agar orang yang bersabar meyakini bahwa kebersamaan Allah menyertainya sehingga ia memperoleh kekuatan yang tidak diperoleh dari kemampuannya sendiri, dan kebersamaan itu merupakan kebersamaan khusus yang berisi pertolongan, dukungan, dan perlindungan bukan kebersamaan umum yang berarti pengetahuan Allah atas seluruh makhluk, dan hikmah itu juga menunjukkan bahwa sabar bukan sikap pasif melainkan sikap yang disertai pertolongan Allah sehingga orang yang bersabar tidak perlu merasa lemah karena yang menyertainya adalah pihak yang Mahakuasa, serta menghasilkan bahwa sabar merupakan sarana memperoleh pertolongan bersama salat sebagaimana ayat itu menggandengkan keduanya sehingga sabar tanpa doa dan salat merupakan sabar yang kehilangan sarana penguatnya','hikmahnya karena kebersamaan Allah berarti orang yang bersabar tidak akan tertimpa musibah lagi sehingga tidak perlu bersabar terus-menerus','hikmahnya agar orang yang bersabar meyakini bahwa ia tidak sendirian sehingga memperoleh kekuatan untuk melanjutkan'],answer:1,explanation:'Q.S. al-Baqarah [2]: 153 berbunyi wahai orang-orang yang beriman mohonlah pertolongan dengan sabar dan salat, sesungguhnya Allah bersama orang-orang yang sabar. Q.S. al-Anfal [8]: 46 juga berbunyi dan bersabarlah, sesungguhnya Allah bersama orang-orang yang sabar. Q.S. Ali Imran [3]: 200 memerintahkan bersabar dan menguatkan kesabaran serta bersiap siaga dan bertakwa agar beruntung. Hadis juga menyebut bahwa pertolongan itu bersama kesabaran. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar disempurnakan pahalanya tanpa perhitungan. Hadis juga menganjurkan doa memohon pertolongan dan menyebut bahwa apabila engkau meminta pertolongan maka mintalah pertolongan kepada Allah. Adapun kebersamaan Allah tidak menjamin pengabulan seluruh keinginan dalam bentuk yang diminta karena pengabulan mengikuti ketentuan Allah yang paling baik menurut ilmu-Nya, dan orang yang bersabar tetap dapat tertimpa musibah karena musibah merupakan ujian yang berlaku bagi seluruh manusia.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam menjaga lisan',text:'Perilaku istiqamah dalam menjaga lisan yang paling tepat adalah ...',options:['menjaga lisan secara berkelanjutan dalam seluruh keadaan termasuk ketika bercanda karena candaan yang mengandung dusta atau menyakiti tetap merupakan dosa, ketika marah karena kemarahan merupakan keadaan yang paling sering menghasilkan ucapan yang disesali, dan ketika bersama teman dekat karena kedekatan sering menghasilkan kelalaian dalam menjaga lisan, tidak menyampaikan informasi yang belum dipastikan kebenarannya karena menyampaikan seluruh yang didengar merupakan bentuk kedustaan, tidak menggunjing, memfitnah, atau mencela walaupun pihak yang dibicarakan tidak hadir dan walaupun pembicaraan itu terasa menghibur, memilih diam ketika tidak ada kebaikan yang dapat diucapkan karena diam merupakan bentuk menjaga diri yang paling mudah, serta mengucapkan perkataan yang baik seperti zikir, nasihat, dan kata yang menghibur pihak yang bersedih sehingga lisan terisi dengan kebaikan bukan hanya terhindar dari keburukan','menjaga lisan hanya ketika berada di tempat yang formal karena di tempat yang tidak formal lisan lebih bebas','menjaga lisan secara berkelanjutan dalam seluruh keadaan termasuk ketika bercanda dan ketika marah','tidak berbicara sama sekali agar terhindar dari seluruh kemungkinan dosa lisan walaupun tidak menyampaikan kebaikan'],answer:0,explanation:'Hadis juga menyebut bahwa barangsiapa beriman kepada Allah dan hari akhir hendaklah berkata yang baik atau diam. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya. Hadis juga menyebut bahwa cukuplah seseorang dikatakan berdusta apabila ia menceritakan segala yang didengarnya. Q.S. Qaf [50]: 18 berbunyi tidak ada satu ucapan pun yang diucapkan melainkan ada di sisinya malaikat pengawas yang selalu hadir. Q.S. al-Hujurat [49]: 12 melarang ghibah. Hadis juga menyebut bahwa jagalah lisanmu dan rumahmu serta menangislah atas dosamu. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Adapun tidak berbicara sama sekali bukan cara yang diajarkan karena menyampaikan kebaikan merupakan kewajiban seperti amar makruf dan nasihat, dan menjaga lisan hanya di tempat formal bukan istiqamah karena istiqamah berarti keteraturan dalam seluruh keadaan.'},
{level:'HOTS',indicator:'Menganalisis hubungan keempat akhlak terpuji dalam membentuk pribadi muslim',text:'Sabar, syukur, istiqamah, dan husnuzan merupakan empat akhlak yang saling melengkapi. Analisis yang paling tepat terhadap hubungan keempatnya adalah ...',options:['keempatnya membentuk pribadi yang teguh karena sabar menghasilkan kemampuan bertahan dalam ketaatan dan dalam menghadapi musibah, tenang karena syukur menghasilkan penghargaan terhadap apa yang diperoleh sehingga tidak disibukkan oleh keinginan yang belum terpenuhi, berkesinambungan karena istiqamah menghasilkan keteraturan amal sehingga amal tidak terhenti ketika semangat menurun, dan bersih hatinya karena husnuzan menghasilkan terhindarnya hati dari penyakit curiga dan dengki sehingga hubungan dengan sesama terjaga, dan hubungan itu juga menunjukkan bahwa kekurangan dalam salah satu dari keempatnya mempengaruhi yang lain karena orang yang tidak bersyukur cenderung tidak sabar ketika nikmat dicabut dan orang yang berburuk sangka cenderung tidak istiqamah dalam menjaga hubungan dengan sesama','keempatnya membentuk pribadi yang teguh dalam ketaatan, tenang dalam menghadapi keadaan, dan bersih hatinya terhadap sesama','keempatnya merupakan akhlak yang berdiri sendiri sehingga dapat dipilih salah satunya sesuai dengan keperluan','keempatnya berkaitan dengan hubungan kepada Allah sehingga tidak berkaitan dengan hubungan kepada sesama manusia'],answer:0,explanation:'Q.S. Ali Imran [3]: 200 memerintahkan bersabar dan menguatkan kesabaran. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Q.S. Fussilat [41]: 30 menggambarkan keutamaan orang yang beristiqamah. Q.S. al-Hujurat [49]: 12 melarang banyak berprasangka. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik yaitu apabila memperoleh nikmat ia bersyukur dan apabila tertimpa musibah ia bersabar. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Q.S. al-Hujurat [49]: 10 berbunyi sesungguhnya orang-orang mukmin itu bersaudara. Adapun keempatnya tidak dapat dipilih salah satunya karena seluruhnya merupakan bagian dari akhlak yang diperintahkan dan saling melengkapi, dan keempatnya berkaitan dengan hubungan kepada Allah dan kepada sesama manusia karena sabar dan syukur mencakup keduanya sedangkan istiqamah dan husnuzan mencakup akhlak terhadap sesama.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dan syukur dalam menghadapi ujian sekolah',text:'Perilaku sabar dan syukur dalam menghadapi ujian sekolah yang paling tepat adalah ...',options:['berdoa saja tanpa belajar karena doa merupakan sarana yang paling kuat dalam memperoleh hasil yang baik','belajar dengan sungguh-sungguh, berdoa, menerima hasil dengan lapang dada, dan bersyukur atas kesempatan belajar','belajar dengan sungguh-sungguh melalui cara yang jujur karena belajar merupakan bentuk sabar dalam ketaatan dan cara yang jujur merupakan bentuk sabar dari maksiat, berdoa memohon kemudahan dan memohon hasil yang baik karena doa merupakan sarana yang selalu tersedia, menerima hasil dengan lapang dada setelah berusaha karena hasil berada dalam ketentuan Allah sedangkan usaha berada dalam pilihannya, bersyukur atas kesempatan belajar dan atas kemampuan yang dimiliki karena kesempatan dan kemampuan merupakan nikmat yang tidak dimiliki oleh seluruh orang, tidak menyontek walaupun keadaan mendesak karena menyontek merupakan bentuk tidak sabar dari maksiat dan menghasilkan keberkahan yang hilang, serta menjadikan hasil ujian sebagai bahan evaluasi untuk memperbaiki cara belajar pada waktu berikutnya bukan sebagai alasan berhenti berusaha','menerima hasil apa pun tanpa berusaha belajar karena hasil telah ditetapkan sehingga usaha tidak mengubah ketentuan'],answer:2,explanation:'Hadis juga menyebut bahwa apabila engkau memohon maka mohonlah kepada Allah dan apabila engkau meminta pertolongan maka mintalah pertolongan kepada Allah. Hadis juga menganjurkan ikatlah untamu lalu bertawakallah, sehingga doa disertai usaha. Q.S. ar-Rad [13]: 11 berbunyi sesungguhnya Allah tidak mengubah keadaan suatu kaum sehingga mereka mengubah keadaan yang ada pada diri mereka sendiri. Hadis juga menyebut bahwa barangsiapa menipu maka ia bukan dari golongan Rasulullah. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Q.S. an-Najm [53]: 39 menyebut bahwa manusia tidak memperoleh melainkan apa yang diusahakannya, sehingga berdoa tanpa belajar bukan cara yang diajarkan dan menerima hasil tanpa berusaha bukan bentuk sabar melainkan bentuk kelalaian.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa sabar itu pada hentakan pertama',text:'Kesabaran yang sesungguhnya merupakan kesabaran pada hentakan pertama. Analisis yang paling tepat terhadap hikmah sebutan tersebut adalah ...',options:['hikmahnya agar manusia menjaga ucapan dan sikap pada saat musibah pertama kali diterima karena pada saat itu reaksi yang muncul merupakan reaksi yang paling jujur dan paling menentukan apakah musibah itu menghasilkan pahala atau menghasilkan dosa, dan hikmah itu juga menunjukkan bahwa kesabaran yang datang setelah reda merupakan kesabaran yang lebih mudah karena perasaan telah tenang sehingga yang dinilai paling berat dan paling bernilai adalah kesabaran pada saat pertama, serta menunjukkan bahwa menjaga ucapan pada saat pertama merupakan latihan yang perlu dipersiapkan sebelum musibah datang karena pada saat itu manusia tidak memiliki kesempatan mempersiapkan diri, dan menunjukkan bahwa kalimat istirja merupakan ucapan yang diajarkan untuk diucapkan pada saat pertama sehingga melatih mengucapkannya dalam keadaan tenang merupakan persiapan yang bermanfaat','hikmahnya agar manusia menjaga ucapan dan sikap pada saat musibah pertama kali diterima karena saat itu merupakan saat yang paling menentukan','hikmahnya agar manusia tidak menunjukkan kesedihan pada saat musibah diterima karena kesedihan merupakan tanda tidak sabar','hikmahnya karena kesabaran setelah musibah reda tidak bernilai sehingga tidak perlu dijaga'],answer:0,explanation:'Hadis juga menyebut bahwa kesabaran itu pada hentakan pertama, ketika Rasulullah bersabda kepada seorang perempuan yang menangis di sisi kubur anaknya bahwa bertakwalah kepada Allah dan bersabarlah, lalu perempuan itu menjawab engkau tidak merasakan musibahku, dan setelah mengetahui bahwa yang menasihatinya adalah Rasulullah ia mendatangi pintu beliau dan tidak menemukan penjaga lalu beliau bersabda sesungguhnya kesabaran itu pada hentakan pertama. Q.S. al-Baqarah [2]: 155-156 memberi kabar gembira kepada orang yang sabar yang mengucapkan kalimat istirja ketika tertimpa musibah. Hadis juga menyebut bahwa tidaklah seorang muslim tertimpa musibah lalu ia mengucapkan kalimat istirja dan berdoa memohon pengganti yang lebih baik melainkan Allah memberinya pengganti yang lebih baik. Hadis juga menyebut bahwa Rasulullah bersedih ketika putranya wafat sambil menyatakan bahwa mata berlinang dan hati bersedih tetapi tidak mengucapkan kecuali yang diridhai Allah, sehingga kesedihan bukan tanda tidak sabar selama tidak disertai ucapan yang menunjukkan ketidakrelaan. Adapun kesabaran setelah musibah reda tetap bernilai walaupun nilainya tidak sebesar kesabaran pada hentakan pertama.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam berinfak walaupun keadaan ekonominya terbatas',text:'Perilaku istiqamah dalam berinfak walaupun keadaan ekonominya terbatas yang paling tepat adalah ...',options:['tetap berinfak secara teratur dengan jumlah yang sesuai kemampuan walaupun sedikit','tetap berinfak secara teratur dengan jumlah yang sesuai kemampuan karena keteraturan merupakan ciri istiqamah dan amal yang berkelanjutan lebih dicintai Allah daripada amal yang banyak tetapi terhenti, tidak menunggu keadaan lapang untuk mulai berinfak karena menunggu lapang sering menghasilkan tidak berinfak sama sekali, mendahulukan nafkah keluarga sebelum berinfak kepada pihak lain karena nafkah keluarga merupakan kewajiban yang mendahului, berinfak dalam bentuk selain harta seperti tenaga, waktu, ilmu, atau menyingkirkan gangguan dari jalan ketika tidak memiliki harta yang dapat diberikan karena seluruh bentuk kebaikan merupakan sedekah, tidak merasa rendah diri karena jumlah infaknya lebih kecil dari orang lain karena penilaian Allah berdasarkan kesungguhan bukan jumlah, serta tidak berinfak dari harta yang haram karena infak dari harta yang haram tidak diterima','berinfak dengan jumlah yang besar walaupun mengabaikan keperluan keluarganya agar infaknya terasa berat sehingga lebih bernilai','tidak berinfak karena keadaan ekonominya terbatas sehingga berinfak dalam keadaan itu hanya menambah kesulitan'],answer:1,explanation:'Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa lindungilah diri kalian dari api neraka walaupun dengan separuh butir kurma dan apabila tidak memiliki maka dengan kata yang baik. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah dan mulailah dari orang yang menjadi tanggunganmu. Hadis juga menyebut bahwa sedekah dapat berupa amar makruf nahi mungkar, menolong orang, menyingkirkan gangguan dari jalan, dan tersenyum kepada saudara. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Hadis juga menyebut bahwa setiap daging yang tumbuh dari yang haram maka neraka lebih utama baginya. Q.S. al-Baqarah [2]: 261 memberi perumpamaan satu biji yang menumbuhkan tujuh tangkai, sehingga jumlah yang sedikit tetap menghasilkan pahala yang berlipat.'},
{level:'HOTS',indicator:'Menganalisis hikmah diperintahkannya menjauhi banyak prasangka',text:'Q.S. al-Hujurat [49]: 12 memerintahkan menjauhi banyak dari prasangka dan menyebut bahwa sebagian prasangka merupakan dosa. Analisis yang paling tepat terhadap hikmah perintah tersebut adalah ...',options:['hikmahnya agar manusia tidak menilai keadaan batin orang lain karena penilaian itu sering keliru akibat keterbatasan informasi dan pengaruh perasaan sendiri, dan penilaian yang keliru menghasilkan dosa serta menghasilkan tindakan yang merugikan pihak yang dinilai tanpa dasar, dan hikmah itu juga menunjukkan bahwa yang diperintahkan adalah menjauhi banyak prasangka bukan seluruhnya karena terdapat prasangka yang diperlukan seperti kewaspadaan terhadap pihak yang menunjukkan tanda bahaya dan kehati-hatian dalam transaksi, serta menunjukkan bahwa prasangka buruk sering melahirkan perbuatan dosa yang lain seperti mencari-cari kesalahan dan menggunjing sehingga menjauhi prasangka buruk merupakan cara memutus rangkaian dosa yang bermula dari hati','hikmahnya karena prasangka merupakan dosa yang paling besar sehingga lebih berbahaya daripada perbuatan dosa yang terlihat','hikmahnya agar manusia tidak menilai keadaan batin orang lain karena penilaian itu sering keliru dan menghasilkan dosa','hikmahnya agar manusia tidak memikirkan perbuatan orang lain sama sekali karena memikirkan merupakan bentuk prasangka'],answer:0,explanation:'Q.S. al-Hujurat [49]: 12 berbunyi wahai orang-orang yang beriman jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa, dan janganlah kalian mencari-cari kesalahan orang lain dan janganlah kalian menggunjing sebagian yang lain. Q.S. an-Najm [53]: 32 melarang menyebut diri sendiri suci karena Allah paling mengetahui tentang orang yang bertakwa. Q.S. al-Isra [17]: 36 melarang mengikuti sesuatu yang tidak diketahui. Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Q.S. al-Hujurat [49]: 6 memerintahkan meneliti kebenaran berita, yang menunjukkan bahwa kehati-hatian tetap diperintahkan sehingga tidak seluruh prasangka dilarang. Hadis juga menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian, sehingga menilai keadaan batin orang lain bukan hak manusia. Adapun prasangka bukan dosa yang paling besar karena dosa yang paling besar adalah mempersekutukan Allah sebagaimana disebut dalam hadis.'},
{level:'HOTS',indicator:'Menentukan perilaku syukur dalam menggunakan anggota tubuh',text:'Perilaku syukur dalam menggunakan anggota tubuh yang paling tepat adalah ...',options:['menggunakan anggota tubuh untuk memperoleh keuntungan dunia sebanyak mungkin karena keuntungan dunia merupakan bentuk memanfaatkan nikmat','menjaga seluruh anggota tubuh dari perbuatan yang dilarang saja karena menggunakan untuk ketaatan bukan bagian dari syukur','menggunakan setiap anggota tubuh untuk ketaatan dan menjaganya dari perbuatan yang dilarang','menggunakan mata untuk melihat yang dibolehkan dan untuk memperoleh ilmu serta tidak menggunakannya untuk melihat yang dilarang, menggunakan telinga untuk mendengar nasihat dan ilmu serta tidak menggunakannya untuk mendengar ghibah dan ucapan yang menyakiti, menggunakan lisan untuk berkata yang baik dan untuk berzikir serta tidak menggunakannya untuk dusta dan celaan, menggunakan tangan untuk bekerja yang halal dan untuk menolong serta tidak menggunakannya untuk mengambil yang bukan haknya, menggunakan kaki untuk melangkah ke tempat ibadah dan tempat yang bermanfaat serta tidak menggunakannya untuk melangkah ke tempat yang dilarang, serta menggunakan akal untuk memahami ayat Allah dan untuk mempertimbangkan keputusan dengan benar karena seluruh anggota tubuh akan dimintai pertanggungjawabannya'],answer:3,explanation:'Q.S. al-Isra [17]: 36 berbunyi dan janganlah engkau mengikuti sesuatu yang tidak engkau ketahui, sesungguhnya pendengaran, penglihatan, dan hati seluruhnya akan dimintai pertanggungjawabannya. Q.S. an-Nur [24]: 24 menyebut bahwa pada hari itu lidah, tangan, dan kaki menjadi saksi atas mereka terhadap apa yang dahulu mereka kerjakan. Q.S. Saba [34]: 13 berbunyi bekerjalah wahai keluarga Daud untuk bersyukur. Hadis juga menyebut bahwa tidak akan bergeser kedua kaki seorang hamba pada hari kiamat hingga ditanya tentang empat perkara di antaranya tentang tubuhnya untuk apa digunakan. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga menyebut bahwa barangsiapa menjamin untuknya apa yang ada di antara kedua rahangnya dan apa yang ada di antara kedua kakinya maka ia menjamin surga baginya. Adapun menjaga dari perbuatan yang dilarang saja bukan syukur yang sempurna karena syukur menuntut penggunaan nikmat sesuai dengan tujuan pemberiannya, dan menggunakan anggota tubuh untuk keuntungan dunia tanpa batas bukan bentuk syukur melainkan bentuk menggunakan nikmat untuk kepentingan yang tidak selalu sesuai dengan tujuannya.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sabar sebagai separuh iman',text:'Sabar disebut sebagai separuh iman dalam riwayat yang lain. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu menunjukkan bahwa sabar merupakan unsur yang menyertai seluruh bagian iman karena beriman kepada Allah memerlukan sabar dalam ketaatan, memerlukan sabar dari maksiat, dan memerlukan sabar atas ketentuan yang tidak sesuai keinginan, sehingga tanpa sabar iman tidak dapat dipertahankan dalam keadaan yang menekan, dan kedudukan itu juga menunjukkan bahwa sabar merupakan pengikat antara keyakinan dan perbuatan karena keyakinan yang tidak disertai kesabaran mudah goyah ketika menghadapi ujian sedangkan keyakinan yang disertai kesabaran menghasilkan perbuatan yang konsisten, serta menunjukkan bahwa sabar merupakan ciri yang membedakan mukmin dari selainnya karena perkara orang mukmin seluruhnya baik melalui syukur dan sabar','kedudukan itu menunjukkan bahwa sabar merupakan separuh dari iman sehingga separuh yang lain tidak memerlukan kesabaran','kedudukan itu berarti sabar lebih utama daripada seluruh rukun iman sehingga rukun iman tidak diperlukan apabila telah sabar','kedudukan itu menunjukkan bahwa sabar merupakan unsur yang menyertai seluruh bagian iman sehingga tanpanya iman tidak utuh'],answer:0,explanation:'Hadis juga menyebut bahwa kebersihan merupakan separuh iman dan sabar merupakan separuh iman dalam riwayat yang menyebut bahwa kesabaran merupakan cahaya. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik yaitu apabila memperoleh nikmat ia bersyukur maka itu baik baginya dan apabila tertimpa musibah ia bersabar maka itu baik baginya. Q.S. al-Baqarah [2]: 153 memerintahkan memohon pertolongan dengan sabar dan salat. Q.S. Ali Imran [3]: 200 memerintahkan bersabar dan menguatkan kesabaran. Hadis Jibril juga menyebut enam rukun iman yang seluruhnya memerlukan kesabaran dalam menjaganya. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar disempurnakan pahalanya tanpa perhitungan. Adapun sabar bukan pengganti rukun iman melainkan sikap yang menyertai pelaksanaannya, dan separuh yang lain dari iman juga memerlukan kesabaran karena iman merupakan satu kesatuan yang tidak dapat dipisahkan.'},
{level:'HOTS',indicator:'Menentukan perilaku husnuzan kepada Allah ketika doa belum dikabulkan',text:'Perilaku husnuzan kepada Allah ketika doa belum dikabulkan yang paling tepat adalah ...',options:['tetap berdoa dengan yakin karena tergesa-gesa merasa doa tidak dikabulkan merupakan penghalang pengabulan, menerima bahwa pengabulan doa dapat berbentuk dikabulkan sesuai permohonan, diganti dengan yang lebih baik, ditangguhkan untuk akhirat, atau ditolak keburukan yang setara dengannya sehingga tidak dikabulkannya dalam bentuk yang diminta bukan tanda bahwa doa itu tidak didengar, memeriksa diri dari hal yang dapat menghalangi pengabulan doa seperti harta yang haram, doa untuk hal yang berdosa, atau memutus silaturahmi, tidak berhenti berdoa karena doa merupakan ibadah yang bernilai sendiri walaupun permohonannya belum terwujud, serta tetap berikhtiar melalui cara yang halal karena doa bukan pengganti usaha melainkan pelengkapnya','berdoa dengan cara yang berbeda yaitu meminta kepada pihak lain yang dianggap lebih dekat kepada Allah agar permohonannya disampaikan','tetap berdoa dengan yakin dan menerima bahwa pengabulan dapat berbentuk yang lebih baik atau ditangguhkan','berhenti berdoa karena doa yang belum dikabulkan menunjukkan bahwa permohonannya tidak baik baginya'],answer:0,explanation:'Hadis juga menyebut bahwa doa setiap hamba dikabulkan selama tidak berdoa untuk dosa atau memutus silaturahmi dan tidak tergesa-gesa. Hadis juga menyebut bahwa tergesa-gesa adalah ketika seseorang berkata aku telah berdoa tetapi tidak dikabulkan lalu ia merasa jenuh dan meninggalkan doa. Q.S. al-Baqarah [2]: 186 berbunyi Aku mengabulkan permohonan orang yang berdoa apabila ia berdoa kepada-Ku. Hadis juga menyebut bahwa Allah mengganti permohonan dengan yang lebih baik atau menangguhkannya untuk akhirat atau menolak keburukan yang setara dengannya. Hadis juga menyebut bahwa doa merupakan ibadah. Hadis juga menganjurkan ikatlah untamu lalu bertawakallah. Hadis juga menyebut bahwa apabila engkau memohon maka mohonlah kepada Allah, sehingga meminta kepada pihak lain agar menyampaikan permohonan bukan cara yang dibenarkan karena doa hanya ditujukan kepada Allah.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya syukur sebagai sebab bertambahnya nikmat',text:'Q.S. Ibrahim [14]: 7 menyebut bahwa bersyukur menghasilkan tambahan nikmat. Analisis yang paling tepat terhadap hikmah ketentuan tersebut adalah ...',options:['hikmahnya agar manusia terdorong bersyukur karena syukur menghasilkan manfaat bagi dirinya sendiri yaitu tambahan nikmat sedangkan Allah tidak memerlukan syukur hamba-Nya karena Dia Mahakaya, dan hikmah itu juga menunjukkan bahwa tambahan nikmat yang dijanjikan dapat berupa tambahan jumlah, tambahan keberkahan sehingga nikmat yang sedikit terasa cukup dan bermanfaat, atau tambahan kemampuan menggunakan nikmat untuk ketaatan sehingga nikmat itu menghasilkan pahala, serta menunjukkan bahwa syukur merupakan cara menjaga nikmat yang telah diperoleh karena nikmat yang tidak disyukuri merupakan nikmat yang terancam dicabut, dan menunjukkan bahwa janji tambahan itu merupakan bentuk kemurahan Allah karena syukur itu sendiri merupakan nikmat yang perlu disyukuri','hikmahnya karena syukur merupakan syarat memperoleh nikmat sehingga orang yang tidak bersyukur tidak pernah memperoleh nikmat sama sekali','hikmahnya agar manusia memperoleh kenikmatan dunia sebanyak mungkin sehingga kehidupan dunianya nyaman','hikmahnya agar manusia terdorong bersyukur karena syukur menghasilkan manfaat bagi dirinya sendiri'],answer:0,explanation:'Q.S. Ibrahim [14]: 7 berbunyi dan ingatlah ketika Tuhanmu memaklumkan jika kalian bersyukur maka Aku menambah nikmat kepada kalian dan jika kalian kufur maka sesungguhnya azab-Ku sangat pedih. Q.S. an-Naml [27]: 40 berbunyi barangsiapa bersyukur maka syukurnya untuk dirinya sendiri dan barangsiapa kufur maka sesungguhnya Tuhanku Mahakaya lagi Mahamulia. Q.S. an-Nahl [16]: 112 menggambarkan negeri yang dahulu aman dan tenteram yang rezekinya melimpah lalu penduduknya mengingkari nikmat Allah sehingga Allah merasakan kepada mereka kelaparan dan ketakutan. Hadis juga menyebut bahwa kekayaan yang hakiki bukan banyaknya harta melainkan kekayaan jiwa. Q.S. al-Baqarah [2]: 152 memerintahkan mengingat Allah dan bersyukur. Hadis juga menyebut bahwa Allah ridha kepada hamba yang memakan makanan lalu memuji Allah atasnya. Adapun orang yang tidak bersyukur tetap memperoleh nikmat di dunia karena Allah memberi rezeki kepada seluruh makhluk, tetapi nikmat itu tidak membawa keberkahan dan dapat dicabut, dan tujuan utama syukur bukan kenyamanan dunia melainkan pengakuan terhadap pemberi nikmat.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam menuntut ilmu sepanjang hayat',text:'Perilaku istiqamah dalam menuntut ilmu sepanjang hayat yang paling tepat adalah ...',options:['menuntut ilmu hanya hingga menyelesaikan pendidikan formal karena pendidikan formal telah memberi ilmu yang cukup','terus menambah ilmu melalui cara yang teratur walaupun telah menyelesaikan pendidikan formal','terus menambah ilmu melalui cara yang teratur seperti membaca, mengikuti kajian, atau belajar dari pihak yang berilmu walaupun telah menyelesaikan pendidikan formal karena keperluan ilmu berubah sesuai dengan perkembangan keadaan dan tanggung jawab, mengutamakan ilmu yang paling diperlukan dalam keadaan sekarang seperti ilmu yang memperbaiki ibadah dan ilmu yang menunjang tanggung jawab pekerjaannya, mengamalkan ilmu yang diperoleh karena ilmu yang tidak diamalkan tidak menghasilkan manfaat dan merupakan hujah yang memberatkan, mengajarkan ilmu kepada pihak lain karena mengajarkan menghasilkan pahala yang berkelanjutan dan menguatkan pemahaman sendiri, tidak merasa cukup dengan ilmu yang telah dimiliki karena merasa cukup merupakan tanda berhentinya perkembangan, serta tidak menuntut ilmu untuk tujuan memperoleh kedudukan atau untuk memenangkan perdebatan karena niat yang keliru menghasilkan ancaman','menuntut ilmu sebanyak mungkin tanpa mengamalkan karena menambah ilmu merupakan amal yang bernilai walaupun tidak diamalkan'],answer:2,explanation:'Hadis juga menyebut bahwa menuntut ilmu merupakan kewajiban atas setiap muslim. Hadis juga menyebut bahwa barangsiapa menempuh jalan untuk mencari ilmu maka Allah mudahkan baginya jalan menuju surga. Hadis juga menyebut bahwa barangsiapa menuntut ilmu untuk bersaing dengan para ulama atau untuk mendebat orang-orang bodoh atau untuk memperoleh perhatian manusia maka ia masuk neraka. Hadis juga menyebut bahwa apabila manusia mati maka terputuslah amalnya kecuali tiga perkara yaitu sedekah jariyah, ilmu yang bermanfaat, dan anak saleh yang mendoakannya, sehingga mengamalkan dan mengajarkan ilmu menghasilkan pahala yang berkelanjutan. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. Thaha [20]: 114 menggambarkan doa memohon tambahan ilmu, yang menunjukkan bahwa menambah ilmu merupakan anjuran yang berkelanjutan. Adapun menuntut ilmu tanpa mengamalkan bukan amal yang bernilai penuh karena ilmu merupakan hujah bagi atau atas pemiliknya.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar ketika menunggu hasil usaha yang lama',text:'Perilaku sabar ketika menunggu hasil usaha yang berlangsung lama yang paling tepat adalah ...',options:['menghentikan usaha lalu memulai usaha yang lain karena usaha yang lama tidak menghasilkan merupakan tanda bahwa usaha itu bukan jalan yang ditetapkan','mengeluhkan lambatnya hasil kepada sebanyak mungkin pihak agar memperoleh dukungan moral sehingga dapat bertahan lebih lama','tetap melaksanakan usaha dan tidak menghentikan karena hasilnya belum terlihat','tetap melaksanakan usaha karena hasil yang belum terlihat bukan tanda bahwa usaha itu tidak akan menghasilkan, sebab sebagian usaha seperti menanam pohon atau menuntut ilmu menghasilkan setelah waktu yang panjang dan bukan dalam waktu yang segera, tidak menilai usahanya gagal hanya karena hasilnya belum tampak karena penilaian yang tergesa menghasilkan penghentian yang disesali kemudian, mengisi waktu menunggu dengan kegiatan lain yang bermanfaat sehingga waktu menunggu tidak menjadi waktu yang terbuang, tidak membandingkan kecepatan hasil usahanya dengan kecepatan hasil usaha orang lain karena perbandingan itu menghasilkan putus asa padahal keadaan setiap orang berbeda, serta berdoa memohon keberkahan atas usahanya dan memohon hasil yang paling baik menurut pengetahuan Allah bukan menurut keinginannya'],answer:3,explanation:'Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa tidaklah seorang muslim menanam pohon atau menabur benih lalu dimakan oleh burung, manusia, atau hewan melainkan hal itu menjadi sedekah baginya, yang menunjukkan bahwa usaha yang hasilnya belum terlihat tetap bernilai. Hadis juga melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah, dan menganjurkan meminta pertolongan kepada Allah serta tidak lemah. Hadis juga menganjurkan doa dan menyebut bahwa tergesa-gesa merupakan penghalang pengabulan. Hadis juga melarang mengeluh kepada manusia dan menyebut bahwa orang yang mengadukan kesedihannya kepada manusia tidak tergolong orang yang sabar, tetapi mengadukan kepada Allah merupakan sunah para nabi sebagaimana Q.S. Yusuf [12]: 86.'},
{level:'HOTS',indicator:'Menganalisis kedudukan istiqamah sebagai sebab turunnya ketenangan',text:'Q.S. Fussilat [41]: 30 menyebut bahwa malaikat turun kepada orang yang beristiqamah dengan mengatakan jangan takut dan jangan bersedih. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu menunjukkan bahwa ketenangan hanya diberikan kepada orang yang beristiqamah dalam seluruh bidang sehingga istiqamah dalam sebagian bidang tidak menghasilkan ketenangan','kedudukan itu menunjukkan bahwa istiqamah menghasilkan ketenangan yang menghilangkan ketakutan dan kesedihan','kedudukan itu menunjukkan bahwa istiqamah menghasilkan ketenangan yang menghilangkan dua perasaan yang paling mengganggu manusia yaitu ketakutan terhadap masa depan dan kesedihan terhadap masa lalu, sebab orang yang beristiqamah meyakini bahwa ia berada di jalan yang benar sehingga tidak takut menghadapi akibat dari jalan itu dan tidak sedih atas apa yang telah ditinggalkannya karena yang ditinggalkannya merupakan hal yang tidak layak dipertahankan, dan kedudukan itu juga menunjukkan bahwa ketenangan itu diberikan oleh Allah melalui malaikat sehingga bukan hasil dari kekuatan jiwa semata melainkan karunia yang menyertai kesungguhan, serta menunjukkan bahwa kabar gembira tentang surga diberikan sebagai penguat sehingga orang yang beristiqamah memperoleh kepastian arah walaupun keadaannya di dunia penuh ketidakpastian','kedudukan itu berarti orang yang beristiqamah tidak menghadapi ketakutan dan kesedihan sama sekali dalam hidupnya di dunia'],answer:2,explanation:'Q.S. Fussilat [41]: 30-31 berbunyi sesungguhnya orang-orang yang berkata Tuhan kami adalah Allah kemudian mereka beristiqamah maka malaikat turun kepada mereka dengan mengatakan janganlah kalian takut dan janganlah bersedih serta bergembiralah dengan surga yang dijanjikan kepada kalian, Kami adalah pelindung-pelindung kalian dalam kehidupan dunia dan di akhirat. Q.S. al-Ahqaf [46]: 13 juga menggambarkan orang yang berkata Tuhan kami adalah Allah kemudian mereka beristiqamah sehingga tidak ada kekhawatiran atas mereka dan mereka tidak bersedih. Q.S. ar-Rad [13]: 28 berbunyi ingatlah hanya dengan mengingat Allah hati menjadi tenteram. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. Hud [11]: 112 memerintahkan beristiqamah dan melarang melampaui batas. Adapun orang yang beristiqamah tetap dapat merasakan takut dan sedih sebagai perasaan manusiawi tetapi perasaan itu tidak menguasainya dan tidak mengubah arahnya, dan istiqamah dalam bidang yang menjadi kewajibannya sudah menghasilkan keutamaan walaupun istiqamah dalam seluruh bidang merupakan keadaan yang lebih sempurna.'},
{level:'HOTS',indicator:'Menentukan perilaku syukur ketika melihat pihak yang keadaannya lebih sulit',text:'Perilaku syukur ketika melihat pihak yang keadaannya lebih sulit yang paling tepat adalah ...',options:['memuji Allah atas keadaannya dan membantu pihak yang lebih sulit sesuai kemampuannya','tidak membandingkan keadaannya dengan keadaan siapa pun karena membandingkan merupakan bentuk tidak menghargai pihak yang lebih sulit','membantu pihak yang lebih sulit secara berlebihan sehingga keadaannya sendiri menjadi sulit karena membantu merupakan bentuk syukur yang paling nyata','memuji Allah atas keadaan yang lebih baik yang dimilikinya karena membandingkan dengan pihak yang keadaannya lebih sulit merupakan cara yang diajarkan untuk tidak meremehkan nikmat Allah, membantu pihak yang lebih sulit sesuai kemampuannya karena melihat kesulitan tanpa membantu merupakan bentuk syukur yang tidak diwujudkan dalam amal, tidak memandang rendah pihak yang lebih sulit karena keadaan merupakan ketentuan Allah yang dapat berubah sehingga tidak ada alasan merasa lebih mulia, tidak menjadikan keadaan yang lebih baik sebagai alasan sombong karena keadaan itu merupakan karunia yang disertai usaha dan dapat dicabut, serta mendoakan kemudahan bagi pihak yang lebih sulit karena doa merupakan bantuan yang dapat diberikan oleh siapa pun tanpa memerlukan kemampuan materi'],answer:3,explanation:'Hadis juga menyebut bahwa lihatlah orang yang di bawah kalian dan jangan melihat orang yang di atas kalian karena yang demikian lebih layak agar kalian tidak meremehkan nikmat Allah. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Q.S. Saba [34]: 13 berbunyi bekerjalah wahai keluarga Daud untuk bersyukur, yang menunjukkan bahwa syukur diwujudkan melalui amal. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Q.S. al-Hujurat [49]: 13 menyebut bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa, sehingga keadaan materi bukan ukuran kemuliaan. Hadis juga menganjurkan mendoakan kebaikan bagi orang lain tanpa kehadirannya karena doa itu mustajab. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga membantu tidak perlu melebihi kemampuan hingga merugikan diri sendiri dan keluarganya.'},
{level:'HOTS',indicator:'Menganalisis hubungan husnuzan dengan keutuhan hubungan persaudaraan',text:'Husnuzan menghasilkan keutuhan hubungan persaudaraan. Analisis yang paling tepat terhadap hubungan tersebut adalah ...',options:['hubungan itu terjadi karena husnuzan menghasilkan pihak yang berbaik sangka tidak pernah mengalami konflik dengan pihak lain','hubungan itu terjadi karena husnuzan mencegah timbulnya penilaian buruk yang menjadi awal permusuhan','hubungan itu berarti husnuzan merupakan satu-satunya syarat keutuhan persaudaraan sehingga syarat yang lain tidak diperlukan','hubungan itu terjadi karena penilaian buruk yang tidak berdasarkan bukti merupakan awal dari rangkaian yang merusak persaudaraan yaitu penilaian buruk melahirkan mencari-cari kesalahan, mencari kesalahan melahirkan menggunjing, menggunjing melahirkan kebencian, dan kebencian melahirkan permutusan hubungan, sehingga husnuzan memutus rangkaian itu pada titik awalnya, dan hubungan itu juga menunjukkan bahwa husnuzan bukan bentuk kelalaian terhadap keburukan yang nyata karena keburukan yang terbukti tetap perlu disikapi melalui nasihat dan peringatan, serta menunjukkan bahwa husnuzan menghasilkan pihak yang diperlakukan dengan baik sangka cenderung membalas dengan sikap yang baik sehingga hubungan menjadi saling menguatkan bukan saling mencurigai'],answer:3,explanation:'Q.S. al-Hujurat [49]: 12 berbunyi jauhilah banyak dari prasangka, sesungguhnya sebagian prasangka itu dosa, dan janganlah kalian mencari-cari kesalahan orang lain dan janganlah kalian menggunjing sebagian yang lain, yang menunjukkan urutan rangkaian dosa yang bermula dari prasangka. Q.S. al-Hujurat [49]: 10 berbunyi sesungguhnya orang-orang mukmin itu bersaudara maka damaikanlah antara kedua saudara kalian dan bertakwalah kepada Allah agar kalian dirahmati. Hadis juga menyebut bahwa tidak halal bagi seorang muslim mendiamkan saudaranya lebih dari tiga hari dan yang terbaik di antara keduanya adalah yang memulai salam. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, sehingga menyampaikan keberatan secara langsung merupakan adab yang menjaga hubungan. Hadis juga menyebut bahwa berbaik sangka merupakan bagian dari ibadah yang baik. Adapun husnuzan bukan satu-satunya syarat keutuhan persaudaraan karena persaudaraan juga memerlukan menunaikan hak, saling menasihati, dan saling membantu, dan husnuzan tidak menghilangkan kemungkinan konflik karena konflik dapat timbul dari perbedaan kepentingan walaupun keduanya berbaik sangka.'},
{level:'HOTS',indicator:'Menentukan perilaku sabar dalam menahan diri dari kemaksiatan yang mudah dilakukan',text:'Perilaku sabar dalam menahan diri dari kemaksiatan yang mudah dilakukan dan tidak diketahui orang lain yang paling tepat adalah ...',options:['menjauhkan diri dari sebab yang mendekatkan kepada kemaksiatan dan mengingat pengawasan Allah','menjauhkan diri dari sebab yang mendekatkan kepada kemaksiatan karena menjauhi sebab merupakan bagian dari menjauhi kemaksiatan itu sendiri sebagaimana larangan mendekati zina menunjukkan bahwa mendekati merupakan larangan tersendiri, mengingat pengawasan Allah dengan meyakini bahwa Allah melihat seluruh perbuatannya dan malaikat mencatatnya sehingga kesadaran pengawasan merupakan penjaga yang paling kuat ketika tidak ada manusia yang mengetahui, mengingat akibat dari kemaksiatan yaitu azab yang kekal dibandingkan dengan kenikmatan sesaat sehingga perbandingannya tidak sebanding, mengganti dorongan kepada kemaksiatan dengan kegiatan yang bermanfaat karena dorongan yang tidak disalurkan kepada kebaikan cenderung mencari jalan kepada keburukan, meminta pertolongan kepada Allah melalui doa memohon perlindungan karena kekuatan menahan diri bukan berasal dari kemampuan diri semata, serta mengingat bahwa meninggalkan sesuatu karena Allah akan diganti dengan yang lebih baik','menghindari keadaan yang menimbulkan dorongan dengan cara mengurung diri sehingga tidak berinteraksi dengan siapa pun','menahan diri dengan mengandalkan kekuatan keinginan sendiri karena mengandalkan kekuatan sendiri lebih pasti berhasil'],answer:1,explanation:'Q.S. al-Isra [17]: 32 berbunyi dan janganlah kalian mendekati zina, sesungguhnya zina itu merupakan perbuatan keji dan jalan yang buruk, sehingga mendekati merupakan larangan tersendiri. Q.S. al-Alaq [96]: 14 berbunyi apakah ia tidak mengetahui bahwa Allah melihat. Q.S. Qaf [50]: 18 menyebut bahwa tidak ada satu ucapan pun yang diucapkan melainkan ada di sisinya malaikat pengawas yang selalu hadir. Hadis juga menyebut bahwa neraka dikelilingi oleh hal-hal yang disukai hawa nafsu. Hadis juga menyebut bahwa sesungguhnya engkau tidak meninggalkan sesuatu karena Allah melainkan Allah menggantinya dengan yang lebih baik bagimu. Hadis juga menganjurkan doa memohon perlindungan dan menyebut bahwa tidak ada daya dan kekuatan kecuali dengan pertolongan Allah, sehingga mengandalkan kekuatan diri sendiri tanpa memohon pertolongan Allah merupakan bentuk merasa cukup yang dapat mengakibatkan kegagalan. Hadis juga menganjurkan bergaul dan bersabar atas gangguan sesama karena muslim yang bergaul dengan masyarakat dan bersabar atas gangguannya lebih baik daripada yang tidak bergaul dan tidak bersabar, sehingga mengurung diri bukan cara yang diajarkan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya sedikitnya hamba yang bersyukur',text:'Q.S. Saba [34]: 13 menyebut bahwa sedikit sekali dari hamba-hamba-Ku yang bersyukur. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya karena syukur merupakan amal yang hanya dapat dilakukan oleh para nabi sehingga manusia biasa tidak mampu melakukannya','hikmahnya agar manusia menyadari bahwa bersyukur merupakan amal yang sulit dilakukan oleh kebanyakan orang sehingga perlu kesungguhan khusus untuk termasuk dalam golongan yang sedikit itu, dan kesadaran itu menghasilkan pemeriksaan terhadap penggunaan nikmat karena syukur bukan sekadar ucapan melainkan penggunaan nikmat sesuai dengan tujuan pemberiannya, serta menghasilkan penghargaan terhadap nikmat yang kecil karena kebanyakan manusia hanya memperhatikan nikmat yang besar dan melupakan nikmat yang hadir terus-menerus seperti kesehatan, keamanan, dan waktu luang, dan menunjukkan bahwa bersyukur merupakan bentuk meneladani keluarga Daud yang diperintahkan bekerja untuk bersyukur sehingga syukur diwujudkan melalui amal bukan melalui perasaan saja','hikmahnya agar manusia berusaha termasuk dalam golongan yang sedikit itu dengan memperhatikan nikmat dan menggunakannya untuk ketaatan','hikmahnya agar manusia tidak merasa bersalah apabila belum dapat bersyukur karena kebanyakan orang juga tidak bersyukur'],answer:1,explanation:'Q.S. Saba [34]: 13 berbunyi mereka membuat untuk Sulaiman apa yang dikehendakinya berupa gedung-gedung yang tinggi, patung-patung, piring-piring yang sebesar kolam, dan periuk-periuk yang tetap di atas tungkunya, bekerjalah wahai keluarga Daud untuk bersyukur, dan sedikit sekali dari hamba-hamba-Ku yang bersyukur. Q.S. an-Nahl [16]: 18 berbunyi dan jika kalian menghitung nikmat Allah niscaya kalian tidak dapat menghitungnya. Hadis juga menyebut bahwa dua nikmat yang banyak manusia tertipu di dalamnya yaitu kesehatan dan waktu luang. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga menyebut bahwa lihatlah orang yang di bawah kalian dan jangan melihat orang yang di atas kalian agar tidak meremehkan nikmat Allah. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Adapun syukur merupakan amal yang dapat dilakukan oleh setiap hamba sehingga bukan amal yang hanya mampu dilakukan oleh para nabi, dan menyadari bahwa kebanyakan orang tidak bersyukur bukan alasan meninggalkan syukur karena yang menjadi ukuran adalah ketaatan bukan kebiasaan kebanyakan orang.'},
{level:'HOTS',indicator:'Menentukan perilaku istiqamah dalam menjaga hubungan silaturahmi',text:'Perilaku istiqamah dalam menjaga hubungan silaturahmi yang paling tepat adalah ...',options:['menyambung hubungan secara teratur walaupun pihak yang disambung tidak membalas dengan baik','menyambung hubungan hanya kepada kerabat yang membalas dengan baik karena menyambung yang tidak membalas hanya menghasilkan kerugian','menyambung hubungan secara teratur melalui kunjungan, komunikasi, atau bantuan walaupun pihak yang disambung tidak membalas dengan baik karena silaturahmi yang paling bernilai adalah yang tetap disambung walaupun diputus oleh pihak lain, tidak memutus hubungan karena perselisihan yang dapat diselesaikan karena mendiamkan saudara lebih dari tiga hari merupakan perbuatan yang dilarang, menunaikan hak kerabat seperti membantu ketika memerlukan dan menghadiri ketika mengundang sesuai kemampuan, memaafkan kekeliruan kerabat dan tidak menghitung-hitung kesalahannya karena menghitung kesalahan menghasilkan pemutusan hubungan, serta mendoakan kerabat dan menyambung hubungan dengan kerabat pihak yang telah wafat karena menyambung hubungan yang demikian merupakan bentuk kesempurnaan silaturahmi','menyambung hubungan pada waktu tertentu saja seperti hari raya karena waktu itu merupakan waktu yang biasa digunakan untuk bersilaturahmi'],answer:2,explanation:'Hadis juga menyebut bahwa bukan penyambung silaturahmi itu orang yang membalas kunjungan, tetapi penyambung silaturahmi adalah orang yang ketika hubungan dengannya diputus ia menyambungnya. Hadis juga menyebut bahwa barangsiapa ingin diluaskan rezekinya dan dikenang jejaknya hendaklah menyambung silaturahmi. Hadis juga menyebut bahwa tidak halal bagi seorang muslim mendiamkan saudaranya lebih dari tiga hari. Hadis juga menyebut bahwa bentuk bakti setelah orang tua wafat termasuk memuliakan sahabat keduanya, sehingga menyambung hubungan dengan kerabat pihak yang telah wafat merupakan kesempurnaan silaturahmi. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menyambung secara teratur merupakan bentuk istiqamah. Hadis juga menganjurkan mendoakan kebaikan bagi orang lain tanpa kehadirannya. Adapun menyambung hanya kepada yang membalas bukan silaturahmi yang utama, dan menyambung hanya pada waktu tertentu merupakan bentuk keteraturan yang kurang karena silaturahmi dianjurkan secara berkelanjutan.'},
{level:'HOTS',indicator:'Menganalisis kedudukan sabar dalam ketaatan sebagai sabar yang paling berkelanjutan',text:'Sabar dalam ketaatan merupakan sabar yang berlangsung sepanjang hayat. Analisis yang paling tepat terhadap kedudukan tersebut adalah ...',options:['kedudukan itu menunjukkan bahwa sabar dalam ketaatan hanya diperlukan untuk ketaatan yang berat seperti puasa dan haji sedangkan ketaatan yang ringan tidak memerlukannya','kedudukan itu menunjukkan bahwa sabar dalam ketaatan memerlukan keberlanjutan sehingga lebih berat daripada sabar yang bersifat sementara','kedudukan itu menunjukkan bahwa sabar dalam ketaatan memerlukan keberlanjutan sepanjang hayat karena ketaatan tidak berhenti pada waktu tertentu sehingga beratnya terletak pada keberlanjutan bukan pada beratnya satu kali pelaksanaan, dan kedudukan itu juga menunjukkan bahwa sabar dalam ketaatan mencakup tiga waktu yaitu sebelum melaksanakan ketaatan dengan meluruskan niat, selama melaksanakan ketaatan dengan menjaga kesungguhan dan tidak membatalkannya, dan sesudah melaksanakan ketaatan dengan tidak menyebut-nyebutnya untuk memperoleh pujian dan tidak merasa cukup dengannya, serta menunjukkan bahwa sabar dalam ketaatan merupakan sabar yang menghasilkan amal karena sabar yang tidak menghasilkan amal bukan sabar yang dimaksud dalam ketaatan','kedudukan itu berarti sabar dalam ketaatan lebih utama daripada sabar dari maksiat sehingga menjaga diri dari maksiat tidak perlu diutamakan'],answer:2,explanation:'Hadis juga membagi sabar menjadi tiga yaitu sabar dalam ketaatan kepada Allah, sabar dari maksiat kepada Allah, dan sabar atas musibah dari Allah. Q.S. Maryam [19]: 65 berbunyi Tuhan langit dan bumi serta apa yang ada di antara keduanya maka sembahlah Dia dan bersabarlah dalam beribadah kepada-Nya. Q.S. Thaha [20]: 132 berbunyi dan perintahkanlah keluargamu untuk mendirikan salat dan bersabarlah dalam mengerjakannya. Q.S. al-Hijr [15]: 99 berbunyi dan sembahlah Tuhanmu hingga datang kepadamu keyakinan yaitu kematian, yang menunjukkan bahwa ketaatan berlangsung sepanjang hayat. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa amal bergantung pada niatnya dan melarang menyebut-nyebut pemberian, sehingga sabar sesudah ketaatan merupakan bagian dari sabar dalam ketaatan. Adapun sabar dari maksiat juga merupakan sabar yang utama dan keduanya tidak dapat dipisahkan karena menjaga ketaatan memerlukan menjauhi maksiat, dan ketaatan yang ringan juga memerlukan kesabaran karena keberlanjutannya merupakan ujian tersendiri.'},
{level:'HOTS',indicator:'Menentukan perilaku syukur dalam menggunakan ilmu yang dimiliki',text:'Perilaku syukur dalam menggunakan ilmu yang dimiliki yang paling tepat adalah ...',options:['mengajarkan ilmu hanya kepada pihak yang menghargainya agar ilmunya tidak disia-siakan oleh pihak yang tidak menghargai','mengamalkan ilmu, mengajarkannya kepada pihak yang memerlukan, dan tidak menyembunyikannya','menyimpan ilmu untuk dirinya sendiri agar ilmunya tetap unggul sehingga kedudukannya tidak tersaingi oleh pihak lain','mengamalkan ilmu yang dimiliki karena ilmu yang tidak diamalkan merupakan hujah yang memberatkan pada hari perhitungan dan merupakan bentuk tidak menggunakan nikmat sesuai dengan tujuan pemberiannya, mengajarkan ilmu kepada pihak yang memerlukan karena ilmu yang diajarkan menghasilkan pahala yang berkelanjutan setelah kematian dan karena menyembunyikan ilmu diancam oleh hadis dengan kendali dari api, tidak menggunakan ilmu untuk memperoleh kedudukan atau untuk memenangkan perdebatan karena niat yang keliru dalam menuntut dan menggunakan ilmu menghasilkan ancaman, mengakui bahwa ilmu yang dimiliki merupakan karunia Allah sehingga tidak sombong atas kepandaian dan tidak merendahkan pihak yang belum memahami, serta terus menambah ilmu karena ilmu yang diperlukan bertambah sesuai dengan perkembangan keadaan dan tanggung jawab'],answer:3,explanation:'Hadis juga menyebut bahwa barangsiapa ditanya tentang suatu ilmu lalu menyembunyikannya maka akan dipakaikan kendali dari api pada hari kiamat. Hadis juga menyebut bahwa apabila manusia mati maka terputuslah amalnya kecuali tiga perkara yaitu sedekah jariyah, ilmu yang bermanfaat, dan anak saleh yang mendoakannya. Hadis juga menyebut bahwa barangsiapa menuntut ilmu untuk bersaing dengan para ulama atau untuk mendebat orang-orang bodoh atau untuk memperoleh perhatian manusia maka ia masuk neraka. Q.S. an-Nahl [16]: 53 berbunyi dan apa pun nikmat yang ada pada kalian maka dari Allah. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. Thaha [20]: 114 menggambarkan doa memohon tambahan ilmu. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya, sehingga mengajarkan ilmu kepada siapa pun yang memerlukan merupakan amal yang dianjurkan tanpa membatasi pada pihak yang menghargai.'},
{level:'HOTS',indicator:'Menganalisis hikmah diperintahkannya istiqamah bersama larangan melampaui batas',text:'Q.S. Hud [11]: 112 memerintahkan istiqamah dan melarang melampaui batas. Analisis yang paling tepat terhadap hikmah penggandengan kedua perintah tersebut adalah ...',options:['hikmahnya agar keteguhan dijaga dalam batas kemampuan sehingga tidak berakhir dengan berhenti sepenuhnya','hikmahnya agar keteguhan dalam beragama dijaga dalam batas kemampuan karena membebani diri melebihi kemampuan sering menghasilkan berhenti sepenuhnya ketika kemampuan itu tidak lagi tersedia, dan hikmah itu juga menunjukkan bahwa istiqamah yang benar merupakan keteraturan dalam kadar yang dapat dipertahankan bukan kesungguhan yang tinggi dalam waktu singkat, serta menunjukkan bahwa melampaui batas dapat berupa menambah ibadah yang tidak diajarkan atau meninggalkan yang dibolehkan dengan maksud mendekatkan diri kepada Allah sehingga kedua bentuk itu bukan bagian dari istiqamah, dan menunjukkan bahwa agama ini mudah sehingga yang diperintahkan adalah kemudahan yang berkelanjutan bukan kesulitan yang mengagumkan tetapi tidak bertahan','hikmahnya karena melampaui batas hanya berkaitan dengan perbuatan maksiat sehingga menambah ibadah tidak termasuk melampaui batas','hikmahnya agar manusia tidak beramal yang banyak karena amal yang banyak berisiko melampaui batas'],answer:1,explanation:'Q.S. Hud [11]: 112 berbunyi maka beristiqamahlah sebagaimana diperintahkan kepadamu dan kepada orang yang bertobat bersamamu serta janganlah melampaui batas, sesungguhnya Dia Maha Melihat apa yang kalian kerjakan. Hadis juga menyebut bahwa agama ini mudah dan tidak ada orang yang mempersulit diri dalam agama melainkan agama itu mengalahkannya, maka berlakulah tepat, mendekatlah, dan bergembiralah. Hadis juga menyebut bahwa beramallah sesuai kemampuan kalian karena Allah tidak jenuh hingga kalian jenuh. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga melarang membebani diri dengan ibadah yang melebihi kemampuan sebagaimana kisah sahabat yang berniat tidak menikah, tidak makan daging, dan salat sepanjang malam lalu Rasulullah menyatakan bahwa beliau salat dan tidur, berpuasa dan berbuka, serta menikah, dan barangsiapa membenci sunah beliau maka ia bukan dari golongan beliau. Adapun amal yang banyak tidak dilarang apabila dalam batas kemampuan, dan melampaui batas mencakup menambah ibadah yang tidak diajarkan bukan hanya perbuatan maksiat.'},
{level:'HOTS',indicator:'Menentukan perilaku husnuzan dan sabar ketika dituduh melakukan perbuatan yang tidak dilakukannya',text:'Perilaku husnuzan dan sabar ketika dituduh melakukan perbuatan yang tidak dilakukannya yang paling tepat adalah ...',options:['menjelaskan keadaan yang sebenarnya dengan bahasa yang tenang dan bukti yang tersedia karena menjelaskan merupakan hak yang perlu ditunaikan agar tuduhan tidak menyebar dan tidak diterima sebagai kebenaran, tidak membalas tuduhan dengan tuduhan serupa karena membalas dengan cara yang dilarang menambah persoalan dan menghasilkan dosa bagi yang membalas, bersabar atas akibat yang timbul dari tuduhan itu selama penjelasan telah disampaikan karena penilaian manusia dapat berubah sedangkan penilaian Allah tidak keliru, memaafkan pihak yang menuduh apabila telah jelas bahwa tuduhannya berasal dari kekeliruan bukan dari niat merusak, meminta bantuan pihak yang berwenang atau yang dihormati untuk meluruskan keadaan apabila penjelasan pribadi tidak diterima, serta meyakini bahwa Allah mengetahui keadaan yang sebenarnya dan akan menampakkan kebenaran pada waktunya','tidak menjelaskan keadaan yang sebenarnya karena menjelaskan merupakan bentuk membela diri yang mengurangi pahala kesabaran','menjelaskan keadaan yang sebenarnya dengan tenang dan menyerahkan penilaian kepada Allah','menyimpan perasaan tidak senang terhadap pihak yang menuduh dan memutus hubungan agar tidak lagi tertuduh'],answer:0,explanation:'Q.S. Yusuf [12]: 26-28 menggambarkan cara Nabi Yusuf menjelaskan keadaan yang sebenarnya ketika dituduh yaitu dengan menunjukkan bukti sehingga kebenaran tampak, yang menjelaskan bahwa membela diri dengan cara yang benar bukan bentuk mengurangi pahala kesabaran. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, sehingga menjelaskan keadaan merupakan bentuk menjaga hubungan dari kesalahpahaman. Q.S. asy-Syura [42]: 40 berbunyi barangsiapa memaafkan dan berbuat baik maka pahalanya atas Allah. Q.S. Ibrahim [14]: 42 berbunyi janganlah engkau mengira Allah lalai dari apa yang diperbuat oleh orang-orang yang zalim. Hadis juga menyebut bahwa tidak halal bagi seorang muslim mendiamkan saudaranya lebih dari tiga hari, sehingga memutus hubungan bukan cara yang dibenarkan. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya, sehingga membalas tuduhan dengan tuduhan serupa bukan sikap yang diajarkan.'}
]});
